def _cell_provenance(cell_id: str) -> str:
    """
    Return the data-origin token for a given cell.

    NASA cells (B0005-B0018): real 18650 LiCoO₂ measurements from the NASA
    PCoE Battery Aging Dataset (Saha & Goebel 2007). Capacity and resistance
    are MEASURED; derived analyses (dQ/dV simulation, EIS decomposition,
    rate capability model) are SIMULATED because they apply physics models
    to those measurements rather than measuring the quantities directly.

    Synthetic cells (Cell1-Cell8): generated by generate_cell_data() using
    physics-informed equations. Nothing in these cells was ever measured by
    an instrument. All analysis is SYNTHETIC.
    """
    if cell_id in NASA_CELL_IDS or cell_id.startswith("S-"):
        return "measured"
    return "synthetic"


def _analysis_provenance(cell_id: str, analysis: str = "derived") -> str:
    """
    Return the provenance token for a specific analysis type.

    Direct cycle measurements (capacity, resistance) follow _cell_provenance.
    Derived analyses (EIS, dQ/dV, rate capability, formation) are SIMULATED
    for NASA cells (physics model on real inputs) and SYNTHETIC for synthetic
    cells (physics model on generated inputs).
    """
    if cell_id in NASA_CELL_IDS or cell_id.startswith("S-"):
        return "measured" if analysis == "cycle" else "simulated"
    return "synthetic"
