@st.dialog("Welcome — Guided Tour")
def _guided_tour_dialog():
    step = st.session_state.get("tour_step", 0)
    title, body = _TOUR_STEPS[step]

    st.progress((step + 1) / len(_TOUR_STEPS))
    st.markdown(f"#### {title}")
    _md_html(f"<div style='font-size:14px;color:#a0aec0;line-height:1.6'>{body}</div>")

    st.markdown("<div style='height:12px'></div>", unsafe_allow_html=True)
    _col_skip, _col_next = st.columns([1, 2])
    with _col_skip:
        if st.button("Skip tour", key="tour_skip", use_container_width=True):
            st.session_state["tour_seen"] = True
            st.rerun()
    with _col_next:
        _is_last = step == len(_TOUR_STEPS) - 1
        if st.button(
            "Finish tour" if _is_last else "Next →",
            key="tour_next", type="primary", use_container_width=True,
        ):
            if _is_last:
                st.session_state["tour_seen"] = True
                st.session_state["page"] = "compliance"
            else:
                st.session_state["tour_step"] = step + 1
            st.rerun()


def render_sidebar(cell_ids: list[str], mode: str, nasa_n: int, synth_n: int,
                   up_meta: dict | None, sev_n: int = 0,
                   active_fdfs: dict | None = None,
                   traj_flag: int = 0) -> str:  # A4: number of flagged cells
    with st.sidebar:
        # Dynamic subtitle based on active mode
        n_cells = len(cell_ids)
        if mode == "severson":
            subtitle = f"{n_cells} Severson 2019 LFP cells · real measured"
        elif mode == "nasa":
            subtitle = f"{n_cells} NASA real cells · leave-cell-out model"
        elif mode == "synthetic":
            subtitle = f"{n_cells} synthetic cells · leave-cell-out model"
        elif mode == "uploaded":
            cell_label = up_meta.get("cell_ids", cell_ids) if up_meta else cell_ids
            subtitle = f"{n_cells} uploaded cell{'s' if n_cells != 1 else ''} · your data"
        else:
            subtitle = f"{nasa_n + synth_n} cells ({synth_n} synthetic + {nasa_n} NASA real) · multi-cell model"

        st.markdown(
            f"<div style='padding:0 4px 16px'>"
            f"<div style='font-size:17px;font-weight:800;color:#ffffff;letter-spacing:0.01em'>⚡ Battery Intel</div>"
            f"<div style='font-size:11px;color:#8896a8;margin-top:3px'>{subtitle}</div>"
            f"</div>",
            unsafe_allow_html=True,
        )

        # A1: Inline page search (replaces 3-column task picker)
        _SIDEBAR_SEARCH_ROUTES = {
            "fleet":      ["fleet", "cells", "monitor", "ranking", "attention", "all cells", "worst"],
            "overview":   ["overview", "cell health", "soh", "status", "check cell"],
            "compliance": ["passport", "eu", "compliance", "regulation", "eol", "battery passport"],
            "decision":   ["decision", "replace", "repurpose", "second life", "what should", "copilot", "ask", "cost", "budget", "risk"],
            "health":     ["health", "degrading", "mechanism", "lli", "lam", "fade", "resistance"],
            "compare":    ["compare", "cluster", "cohort", "side by side", "explore"],
            "configure":  ["import", "settings", "upload", "configure", "data source", "threshold"],
            "live_monitor": ["live", "mqtt", "streaming", "bms", "anomaly"],
        }
        _sb_query = st.text_input(
            "search", placeholder="Search pages…",
            key="_sidebar_search", label_visibility="collapsed",
        )
        if _sb_query and _sb_query != st.session_state.get("_last_sb_search", ""):
            st.session_state["_last_sb_search"] = _sb_query
            _sq = _sb_query.lower().strip()
            _best_dest, _best_score = "fleet", 0
            for _dest, _kws in _SIDEBAR_SEARCH_ROUTES.items():
                _sc = sum(1 for k in _kws if k in _sq)
                if _sc > _best_score:
                    _best_score, _best_dest = _sc, _dest
            if _best_score == 0:
                # fall through to copilot with free-text
                _best_dest = "decision"
                st.session_state["copilot_free_text"] = _sb_query
            st.session_state.page = _best_dest
            st.rerun()
        # Quick-access strip (single row, compact)
        _qa1, _qa2, _qa3 = st.columns(3)
        with _qa1:
            if st.button("Fleet", key="qa_fleet", use_container_width=True):
                st.session_state.page = "fleet"; st.rerun()
        with _qa2:
            if st.button("Cell", key="qa_cell", use_container_width=True):
                st.session_state.page = "overview"; st.rerun()
        with _qa3:
            if st.button("Passport", key="qa_passport", use_container_width=True):
                st.session_state.page = "compliance"; st.rerun()
        st.markdown("<div style='height:4px'></div>", unsafe_allow_html=True)

        # ── Data source (collapsed by default) ──
        with st.expander("Data source", expanded=False):
            render_mode_switcher(nasa_n, synth_n, up_meta, sev_n=sev_n)

        # ── Role selector (A2: compact inline — no nested expander) ──
        st.markdown("<div style='height:8px'></div>", unsafe_allow_html=True)
        _cur_role = st.session_state.get("user_role", "Engineer")
        _role_icons = {"Engineer": "⚙", "Fleet Manager": "🗂", "Executive": "📊"}
        _role_icon = _role_icons.get(_cur_role, "⚙")
        _rc1, _rc2 = st.columns([4, 1])
        with _rc1:
            st.markdown(
                f"<div style='font-size:11px;color:#8896a8;padding:4px 0 2px'>"
                f"{_role_icon} <span style='color:#e2e8f0;font-weight:600'>{_cur_role}</span></div>",
                unsafe_allow_html=True,
            )
        with _rc2:
            if st.button("↺", key="change_role_btn", use_container_width=True,
                         help="Switch role (Engineer / Fleet Manager / Executive)"):
                st.session_state["role_chosen"] = False
                st.rerun()

        # ── Nav (grouped) ──
        st.markdown("<div style='height:8px'></div>", unsafe_allow_html=True)
        if "page" not in st.session_state:
            st.session_state.page = "overview"
        current_page = st.session_state.page

        # A4: Persistent trajectory match chip — visible from any page
        if traj_flag > 0:
            _chip_col = "#ef4444" if traj_flag >= 2 else "#f59e0b"
            if st.button(
                f"⚠ {traj_flag} cell{'s' if traj_flag != 1 else ''} flagged",
                key="traj_chip_sidebar",
                use_container_width=True,
                help="Failure trajectory matches detected — click to view in Fleet",
            ):
                st.session_state.page = "fleet"
                st.rerun()
            st.markdown(
                f"<div style='font-size:10px;color:{_chip_col};margin:-6px 0 6px 4px;"
                f"padding:0 2px'>Failure trajectory match</div>",
                unsafe_allow_html=True,
            )

        for group_label, group_items in NAV_GROUPS:
            st.markdown(
                f"<div style='font-size:10px;font-weight:700;color:#4a5568;"
                f"text-transform:uppercase;letter-spacing:0.1em;"
                f"padding:10px 4px 4px;margin-top:2px'>{group_label}</div>",
                unsafe_allow_html=True,
            )
            for label, key in group_items:
                if st.button(
                    label, key=f"nav_{key}", use_container_width=True,
                    type="primary" if current_page == key else "secondary",
                ):
                    st.session_state.page = key
                    st.rerun()

        # Derive chemistry from active mode — stored for page-level display
        _mode_chem = st.session_state.get("data_mode", "synthetic")
        _chem_label = {
            "severson":  "LFP (Severson 2019)",
            "nasa":      "LiCoO₂ NCA (NASA PCoE)",
            "synthetic": "LiCoO₂ (synthetic)",
            "uploaded":  "User-defined",
        }.get(_mode_chem, "LiCoO₂")
        st.session_state["active_chemistry"] = _chem_label

        # ── Cell selector ──
        st.markdown("<div style='height:16px'></div>", unsafe_allow_html=True)
        st.markdown(
            "<div style='font-size:11px;font-weight:600;color:#4a5568;text-transform:uppercase;"
            "letter-spacing:0.08em;padding:0 4px 8px'>Cell</div>",
            unsafe_allow_html=True,
        )
        # Apply any pending Prev/Next navigation BEFORE the selectbox renders.
        # Newer Streamlit raises StreamlitAPIException if you set a widget-keyed
        # session state value after that widget has already been instantiated in
        # the current run, so we use a proxy key "_nav_cell" and consume it here.
        if "_nav_cell" in st.session_state:
            _nav_target = st.session_state.pop("_nav_cell")
            if _nav_target in cell_ids:
                st.session_state["selected_cell"] = _nav_target
        # Determine default index — preserve current selection when cell list changes
        _cur_sel = st.session_state.get("selected_cell")
        _sel_idx = cell_ids.index(_cur_sel) if _cur_sel in cell_ids else 0
        selected = st.selectbox(
            "Select cell",
            options=cell_ids,
            index=_sel_idx,
            key="selected_cell",
            label_visibility="collapsed",
        )

        # Prev / Next quick navigation — write to proxy key, not widget key
        _cur_idx = cell_ids.index(selected)
        _nav_prev, _nav_next = st.columns(2)
        with _nav_prev:
            if st.button("← Prev", key="cell_prev", use_container_width=True,
                         disabled=(_cur_idx == 0)):
                st.session_state["_nav_cell"] = cell_ids[_cur_idx - 1]
                st.rerun()
        with _nav_next:
            if st.button("Next →", key="cell_next", use_container_width=True,
                         disabled=(_cur_idx == len(cell_ids) - 1)):
                st.session_state["_nav_cell"] = cell_ids[_cur_idx + 1]
                st.rerun()

        # ── Fleet alerts (directly after Prev/Next) ──
        if active_fdfs:
            _soh_thresh  = float(st.session_state.get("soh_alert_pct", 85))
            _res_mult    = float(st.session_state.get("resistance_alert_mult", 1.8))
            _spread_thresh = float(st.session_state.get("spread_alert_pct", 5.0))
            _alert_msgs  = []
            for _cid, _fdf in active_fdfs.items():
                _latest = _fdf.iloc[-1]
                if float(_latest.get("soh_pct", 100)) < _soh_thresh:
                    _alert_msgs.append(("warn", f"**{_cid}** SOH {float(_latest['soh_pct']):.1f}% — below {_soh_thresh:.0f}%"))
                if "resistance_ohm" in _fdf.columns and len(_fdf) > 1:
                    _r_init = float(_fdf["resistance_ohm"].iloc[0])
                    _r_now  = float(_latest.get("resistance_ohm", 0))
                    if _r_init > 0 and _r_now > _r_init * _res_mult:
                        _alert_msgs.append(("error", f"**{_cid}** R = {_r_now/_r_init:.2f}× initial"))
            if len(active_fdfs) > 1:
                _soh_vals = [float(fdf["soh_pct"].iloc[-1]) for fdf in active_fdfs.values()]
                _spread   = max(_soh_vals) - min(_soh_vals)
                if _spread > _spread_thresh:
                    _alert_msgs.append(("warn", f"**Fleet spread** {_spread:.1f}% SOH range"))
            if _alert_msgs:
                st.markdown("<div style='height:8px'></div>", unsafe_allow_html=True)
                _label = f"🔔 {len(_alert_msgs)} Alert{'s' if len(_alert_msgs) > 1 else ''}"
                with st.expander(_label, expanded=False):
                    for _kind, _msg in _alert_msgs:
                        if _kind == "error":
                            st.error(_msg)
                        else:
                            st.warning(_msg)

        # ── Cell annotation — compact one-liner ──
        if mode == "uploaded":
            temp_assumed_cells = (up_meta or {}).get("temperature_assumed_cells", [])
            temp_assumed = selected in temp_assumed_cells
            _ann_color, _ann_text = ("#63b3ed", "Uploaded · T " + ("assumed" if temp_assumed else "measured"))
        elif mode == "nasa":
            _ann_color, _ann_text = "#48bb78", "NASA PCoE · real · T=24°C · 2A"
        elif mode == "severson":
            _ann_color, _ann_text = "#48bb78", "Severson 2019 · real · LFP"
        else:
            p = CELL_STRESS_PROFILES.get(selected, {})
            sf = _stress_factor(p.get("temp_mean", 25), p.get("c_rate", 1), p.get("dod", 1))
            _ann_color, _ann_text = "#fc8181", f"Synthetic · {sf:.2f}× stress · T={p.get('temp_mean',25):.0f}°C"
        st.markdown(
            f"<div style='font-size:10px;color:{_ann_color};padding:4px 4px 0'>{_ann_text}</div>",
            unsafe_allow_html=True,
        )

        # D4: Command palette — button only, no fragile JS keyboard injection
        st.markdown("<div style='height:8px'></div>", unsafe_allow_html=True)
        if st.button("Search pages…", key="cmd_palette_btn", use_container_width=True,
                     help="Search pages and navigate quickly"):
            _command_palette_dialog()

        # Theme toggle — separate widget key from the state key it drives,
        # since Streamlit forbids setting a widget-keyed session_state value
        # after the widget has been instantiated this run.
        st.markdown("<div style='height:8px'></div>", unsafe_allow_html=True)
        _lm_current = st.session_state.get("light_mode", False)
        _lm_toggle = st.toggle("Light mode", value=_lm_current, key="light_mode_toggle")
        if _lm_toggle != _lm_current:
            st.session_state["light_mode"] = _lm_toggle
            st.rerun()

    return selected


# ---------------------------------------------------------------------------
# Chart base layout helper
# ---------------------------------------------------------------------------

def base_layout(**overrides) -> dict:
    # Plotly 6 strict validation: do NOT pass `legend` or `title` here.
    # They must go in a separate fig.update_layout(legend=..., title=...) call.
    # Passing them through **base_layout() raises ValueError on Plotly 6+.
    _light = st.session_state.get("light_mode", False)
    _font_c = "#4a5568" if _light else "#a0aec0"
    _grid_c = "#e2e8f0" if _light else "#232d3b"
    _line_c = "#cbd5e0" if _light else "#2d3748"
    layout = dict(
        paper_bgcolor="rgba(0,0,0,0)",
        plot_bgcolor="rgba(0,0,0,0)",
        font=dict(color=_font_c, size=12),
        margin=dict(l=10, r=10, t=36, b=10),
        hovermode="x unified",
    )
    # Merge (not replace) so a caller-supplied xaxis/yaxis dict (e.g. just a
    # custom title or range) still inherits theme-aware grid/line colors
    # unless it explicitly overrides them itself.
    _default_axis = dict(gridcolor=_grid_c, linecolor=_line_c, zeroline=False)
    for _axis_key in ("xaxis", "yaxis"):
        _caller_axis = overrides.pop(_axis_key, None)
        _merged = dict(_default_axis)
        if _caller_axis:
            _merged.update(_caller_axis)
        layout[_axis_key] = _merged
    layout.update(overrides)
    return layout


def soh_status(soh: float) -> tuple[str, str]:
    if soh >= 90: return "Healthy",    "hero-green"
    if soh >= 80: return "Degrading",  "hero-yellow"
    return "End of Life", "hero-red"


# ---------------------------------------------------------------------------
# Feature label map
# ---------------------------------------------------------------------------

FEATURE_LABELS = {
    "cycle_number":        "Cycle age",
    "fade_rate_10cy":      "Fade rate (10-cy)",
    "fade_rate_30cy":      "Fade rate (30-cy)",
    "fade_rate_50cy":      "Fade rate (50-cy)",
    "fade_acceleration":   "Fade acceleration",
    "soh_velocity_50cy":   "SOH velocity",
    "resistance_ohm":      "Internal resistance",
    "resistance_normalized": "Resistance (norm.)",
    "resistance_trend_30cy": "Resistance trend",
    "temp_rolling_30cy":   "Temperature (30-cy avg)",
    "c_rate_rolling_10cy": "C-rate (10-cy avg)",
    "stress_index":        "Composite stress index",
    "dod_proxy":           "Depth of Discharge (proxy)",
}

def friendly(name: str) -> str:
    return FEATURE_LABELS.get(name, name.replace("_", " ").title())


def _soh_sparkline_svg(soh_series: "pd.Series", width: int = 120, height: int = 32) -> str:
    """Inline SVG mini-chart of recent SOH trend (last 50 cycles)."""
    vals = soh_series.dropna().tail(50).tolist()
    if len(vals) < 2:
        return ""
    lo, hi = min(vals), max(vals)
    span = hi - lo if hi > lo else 1.0
    pad = 2
    w, h = width - pad * 2, height - pad * 2
    pts = []
    for i, v in enumerate(vals):
        x = pad + i / (len(vals) - 1) * w
        y = pad + (1 - (v - lo) / span) * h
        pts.append(f"{x:.1f},{y:.1f}")
    polyline = " ".join(pts)
    # Colour: green if last >= first, red if declining steeply
    delta = vals[-1] - vals[0]
    stroke = "#48bb78" if delta >= -0.5 else ("#f6ad55" if delta >= -2 else "#fc8181")
    return (
        f'<svg width="{width}" height="{height}" viewBox="0 0 {width} {height}" '
        f'xmlns="http://www.w3.org/2000/svg" style="display:inline-block;vertical-align:middle">'
        f'<polyline points="{polyline}" fill="none" stroke="{stroke}" stroke-width="1.5" '
        f'stroke-linecap="round" stroke-linejoin="round"/>'
        f'</svg>'
    )


# ---------------------------------------------------------------------------
# Trajectory match card
# ---------------------------------------------------------------------------

def _render_trajectory_match_card(
    cell_id: str,
    df: "pd.DataFrame",
    trajectory_memory: "TrajectoryMemory | None",
) -> None:
    """
    Run the trajectory pattern matcher and render the warning card if a match
    is found.  Called from page_overview and (in summary form) page_fleet.
    """
    if trajectory_memory is None:
        return
    try:
        match = trajectory_memory.match(cell_id, df)
    except Exception:
        return
    if match is None:
        return

    # Colour scheme by severity
    _colours = {
        "critical": ("#7f1d1d", "#fca5a5", "#ef4444"),
        "high":     ("#451a03", "#fcd34d", "#f59e0b"),
        "watch":    ("#0c1a3d", "#93c5fd", "#3b82f6"),
    }
    _bg, _text, _border = _colours.get(match.warning_level, _colours["watch"])
    _icon = "⚠" if match.warning_level == "critical" else ("▲" if match.warning_level == "high" else "●")
    _level_label = match.warning_level.upper()

    _sim_pct = int(match.best_similarity * 100)
    _cells_str = ", ".join(match.matched_cells[:3])
    if match.n_matches > 3:
        _cells_str += f" +{match.n_matches - 3} more"

    # Recommendation sentence
    _action_cycle = match.predicted_eol_min - 5
    _rec = (
        f"Schedule replacement before cycle {_action_cycle:,}."
        if _action_cycle > match.current_cycle
        else "Immediate inspection recommended — estimated EOL is imminent."
    )

    _md_html(
        f"""<div style="
            background:{_bg};
            border:1px solid {_border};
            border-left:4px solid {_border};
            border-radius:8px;
            padding:14px 18px;
            margin-bottom:16px;
        ">
          <div style="font-size:11px;font-weight:700;letter-spacing:0.08em;
                      color:{_text};margin-bottom:6px">
            {_icon} TRAJECTORY MATCH — {_level_label}
          </div>
          <div style="font-size:13px;color:#e2e8f0;line-height:1.6;margin-bottom:8px">
            This cell's degradation trajectory closely matches
            <strong style="color:{_text}">{match.n_matches}
            {"cell" if match.n_matches == 1 else "cells"}</strong>
            that reached end-of-life in the training data
            (best match: <strong style="color:{_text}">{match.best_cell_id}</strong>,
            {_sim_pct}% similarity · <em>{match.failure_mode}</em>).
          </div>
          <div style="display:flex;gap:24px;margin-bottom:10px">
            <div>
              <div style="font-size:10px;color:#94a3b8;text-transform:uppercase;
                          letter-spacing:0.07em">You are at</div>
              <div style="font-size:20px;font-weight:700;color:#e2e8f0">
                Cycle {match.current_cycle:,}
              </div>
              <div style="font-size:11px;color:#94a3b8">SOH {match.current_soh:.1f}%</div>
            </div>
            <div>
              <div style="font-size:10px;color:#94a3b8;text-transform:uppercase;
                          letter-spacing:0.07em">Est. cycles remaining</div>
              <div style="font-size:20px;font-weight:700;color:{_text}">
                {match.cycles_remaining_min}–{match.cycles_remaining_max}
              </div>
              <div style="font-size:11px;color:#94a3b8">
                before EOL · based on {match.n_matches} matched {"trajectory" if match.n_matches == 1 else "trajectories"}
              </div>
            </div>
            <div>
              <div style="font-size:10px;color:#94a3b8;text-transform:uppercase;
                          letter-spacing:0.07em">Predicted EOL window</div>
              <div style="font-size:20px;font-weight:700;color:{_text}">
                Cycle {match.predicted_eol_min:,}–{match.predicted_eol_max:,}
              </div>
              <div style="font-size:11px;color:#94a3b8">
                Matched cells: {_cells_str}
              </div>
            </div>
          </div>
          <div style="font-size:12px;color:{_text};font-weight:600">
            → {_rec}
          </div>
        </div>"""
    )


# ---------------------------------------------------------------------------
# Page: Overview
# ---------------------------------------------------------------------------

def page_overview(df: pd.DataFrame, split_cycle: int, cell_id: str,
                  rul_reliable: bool = True, bundle: dict | None = None,
                  trajectory_memory: "TrajectoryMemory | None" = None):
    _action_bar("overview")
    st.markdown(f"# Is {cell_id} healthy right now?")

    _rdf = _resample_df(df)   # downsampled for charts; df still used for latest/computations
    latest         = df.iloc[-1]
    current_soh    = latest["soh_pct"]
    current_rul    = latest["rul_pred"]
    current_cycle  = int(latest["cycle_number"])
    total_fade     = latest["capacity_fade_ah"]
    confidence     = latest["confidence_tag"]
    status_label, status_colour = soh_status(current_soh)

    # Quantile interval (populated by predict() for calibrated cells)
    rul_q10 = float(latest["rul_q10"]) if "rul_q10" in latest.index else None
    rul_q90 = float(latest["rul_q90"]) if "rul_q90" in latest.index else None

    # SoP from features (computed by build_features)
    sop_pct = float(latest["sop_pct"]) if "sop_pct" in latest.index else None

    # Per-cell fold R² — drives confidence inline reason
    fold_r2 = None
    if bundle is not None:
        cell_fold = bundle["metrics"].get("lco_per_cell", {}).get(cell_id, {})
        fold_r2   = cell_fold.get("rul_r2", None)

    # RUL display: suppress when model doesn't generalise (LCO R² < floor)
    # or when early-cycle features haven't stabilised yet.
    rul_calibrating = (not rul_reliable) or (confidence == "Calibrating")
    rul_display     = "—" if rul_calibrating else f"{current_rul:.0f}"
    rul_sub         = "not calibrated" if not rul_reliable else "cycles to 80% SOH"

    # Application EOL threshold — adjust displayed RUL after rul_calibrating is known
    app_eol = float(st.session_state.get("eol_threshold_pct", 80.0))
    adj_rul = current_rul
    if not rul_calibrating and current_rul is not None and app_eol != 80.0:
        fade_50 = float(latest.get("fade_rate_50cy", 0)) * 100  # SOH %/cy
        if fade_50 > 1e-6:
            adj_rul = max(0, (current_soh - app_eol) / fade_50)
        rul_display = f"{adj_rul:.0f}"
        rul_sub     = f"cycles to {app_eol:.0f}% SOH (app threshold)"

    if rul_calibrating:
        if fold_r2 is not None and fold_r2 > 0:
            _pct_to_thresh = min(99, int(fold_r2 / RUL_RELIABLE_FLOOR * 100))
            conf_html = (
                f"<span class='tag-calibrating'>"
                f"Calibrating — {_pct_to_thresh}% to reliability</span>"
            )
        elif current_cycle < 40:
            _cycles_needed = max(1, 40 - current_cycle)
            conf_html = (
                f"<span class='tag-calibrating'>"
                f"Calibrating — needs {_cycles_needed} more cycles</span>"
            )
        else:
            conf_html = "<span class='tag-calibrating'>Calibrating</span>"
    else:
        conf_html = (
            f"<span class='tag-model'>MODEL"
            + (f" · R²={fold_r2:.2f}" if fold_r2 is not None else "")
            + "</span>"
        )
    rul_hero = "Not calibrated" if not rul_reliable else f"Est. {current_rul:.0f} cycles remaining"

    # Confidence inline reason (two non-engineer templates per CTO spec)
    if rul_calibrating and not rul_reliable:
        if fold_r2 is not None:
            conf_reason = (
                "RUL not calibrated — model accuracy insufficient for this cell's "
                f"degradation profile (held-out fold R²={fold_r2:.2f}, below 0.30 reliability floor)"
            )
        else:
            conf_reason = (
                "RUL not calibrated — model accuracy insufficient for this cell's degradation profile"
            )
    elif not rul_calibrating and fold_r2 is not None:
        conf_reason = (
            f"RUL predictions were tested against data this cell never trained on "
            f"(leave-cell-out validation) — fold R²={fold_r2:.2f} (reliable above 0.30 floor)"
        )
    else:
        conf_reason = None

    # Time estimate: cycles/day from test_date if present, else assume 1 cycle/day
    if "test_date" in df.columns and df["test_date"].notna().any():
        dates = pd.to_datetime(df["test_date"].dropna())
        span_days = max((dates.iloc[-1] - dates.iloc[0]).days, 1)
        cycles_per_day = len(df) / span_days
        rate_note = f"estimated at {cycles_per_day:.1f} cycle/day from data"
    else:
        cycles_per_day = 1.0
        rate_note = "estimated at 1 cycle/day assumption"
    months_remaining = None
    if not rul_calibrating and current_rul is not None and cycles_per_day > 0:
        months_remaining = current_rul / cycles_per_day / 30.44

    is_nasa = cell_id in NASA_CELL_IDS
    if is_nasa:
        source_tag = "NASA real · 24°C · 2A discharge"
    else:
        p  = CELL_STRESS_PROFILES.get(cell_id, {})
        sf = _stress_factor(p.get("temp_mean",25), p.get("c_rate",1.0), p.get("dod",1.0))
        source_tag = f"Synthetic · Stress {sf:.2f}x baseline"

    sparkline_svg = _soh_sparkline_svg(df["soh_pct"])
    interval_html = ""
    # D5: epistemic vs aleatoric uncertainty explanation
    _unc_explanation = ""
    if not rul_calibrating and rul_q10 is not None and rul_q90 is not None and rul_q90 > rul_q10:
        _band_width = rul_q90 - rul_q10
        _band_pct   = _band_width / max(float(current_rul), 1) * 100 if current_rul else 0
        if _band_pct > 40:
            # Wide band — diagnose source
            if current_cycle < 60:
                _unc_explanation = (
                    f"Wide uncertainty ({_band_width:.0f}-cycle spread) because this cell has only "
                    f"{current_cycle} cycles — the model hasn't seen enough of its degradation curve "
                    f"(epistemic). Uncertainty will narrow as cycles accumulate."
                )
            elif fold_r2 is not None and fold_r2 < 0.55:
                _unc_explanation = (
                    f"Wide uncertainty ({_band_width:.0f}-cycle spread) reflects genuine cell-to-cell "
                    f"variability in this chemistry — the model has enough data but the degradation "
                    f"pathway is inherently variable (aleatoric, R²={fold_r2:.2f})."
                )
            else:
                _unc_explanation = (
                    f"Uncertainty band spans {_band_width:.0f} cycles ({_band_pct:.0f}% of median RUL). "
                    f"Mix of data sparsity and chemistry variability — "
                    f"interval will tighten with more cycles."
                )
        elif _band_pct > 15:
            _unc_explanation = (
                f"Moderate uncertainty ({_band_width:.0f}-cycle band). "
                f"Model is well-calibrated; remaining spread reflects natural cycle-to-cycle variation."
            )
        interval_html = (
            f"<div style='font-size:11px;color:#8896a8;margin-top:4px'>"
            f"80% interval: <strong style='color:#a0aec0'>{rul_q10:.0f}–{rul_q90:.0f} cycles</strong>"
            + (f"&nbsp;·&nbsp;<span style='color:#4a5568'>{_unc_explanation}</span>" if _unc_explanation else "")
            + f"</div>"
        )

    _md_html(
        f"""
        <div class="hero-card" role="region" aria-label="Battery status for cell {cell_id}">
            <div class="hero-label" aria-hidden="true">Battery Status · {cell_id}</div>
            <div class="hero-value {status_colour}" role="status" aria-label="Health status: {status_label}">{status_label}</div>
            <div class="hero-sub">
                SOH: <strong style="color:#e2e8f0">{current_soh:.1f}%</strong>
                &nbsp;<span role="img" aria-label="SOH trend sparkline">{sparkline_svg}</span>&nbsp;
                &nbsp;·&nbsp; {rul_hero}
                &nbsp;·&nbsp; {source_tag}
                &nbsp;·&nbsp; {conf_html}
            </div>
            {interval_html}
        </div>
        """
    )

    if conf_reason:
        conf_c = "#fc8181" if (rul_calibrating and not rul_reliable) else "#4a5568"
        st.markdown(
            f"<div style='font-size:12px;color:{conf_c};margin:-8px 0 12px;"
            f"padding:6px 12px;background:#1a202c;border-radius:6px;"
            f"border-left:3px solid {conf_c}'>{conf_reason}</div>",
            unsafe_allow_html=True,
        )

    # ── Plain-English summary sentence ───────────────────────────────────────
    if rul_calibrating:
        _plain_sentence = (
            f"This cell has completed {current_cycle:,} cycles at {current_soh:.1f}% SOH — "
            f"RUL cannot be estimated reliably for this cell's degradation profile."
        )
    elif months_remaining is not None and months_remaining > 0:
        _action = (
            "no immediate action required" if current_soh >= 85
            else "consider inspection or load reduction" if current_soh >= 80
            else "replacement or second-life evaluation recommended"
        )
        _plain_sentence = (
            f"This cell is estimated to need replacement in approximately "
            f"{months_remaining:.0f} months ({current_rul:.0f} cycles) at current usage — {_action}."
        )
    else:
        _plain_sentence = (
            f"This cell has completed {current_cycle:,} cycles at {current_soh:.1f}% SOH."
        )
    st.markdown(
        f"<div style='font-size:14px;color:#a0aec0;margin:-4px 0 18px;"
        f"padding:10px 16px;background:#1a202c;border-radius:8px;"
        f"border-left:3px solid #2d3748'>{_plain_sentence}</div>",
        unsafe_allow_html=True,
    )

    # ── Benchmark comparison (M4) ────────────────────────────────────────────
    try:
        _bm_fdfs = bundle.get("featured_dfs") or {}
        if len(_bm_fdfs) >= 3:
            _peer_sohs = []
            for _bm_cid, _bm_df in _bm_fdfs.items():
                if _bm_cid != selected and "soh_pct" in _bm_df.columns:
                    _peer_last = _bm_df["soh_pct"].dropna()
                    if len(_peer_last):
                        _peer_sohs.append(float(_peer_last.iloc[-1]))
            if _peer_sohs:
                import numpy as _np_bm
                _pct_rank = int((_np_bm.array(_peer_sohs) < current_soh).sum() / len(_peer_sohs) * 100)
                _bm_med   = float(_np_bm.median(_peer_sohs))
                _bm_col   = "#48bb78" if _pct_rank >= 60 else "#d69e2e" if _pct_rank >= 30 else "#e53e3e"
                _bm_word  = "better than" if _pct_rank >= 60 else "in line with" if _pct_rank >= 30 else "below"
                st.markdown(
                    f"<div style='font-size:12px;color:#8896a8;margin:-12px 0 16px;"
                    f"padding:7px 14px;background:#111827;border-radius:6px;"
                    f"border-left:3px solid {_bm_col}'>"
                    f"Fleet benchmark: this cell's SOH is "
                    f"<strong style='color:{_bm_col}'>{_bm_word} {_pct_rank}% of fleet peers</strong> "
                    f"(fleet median {_bm_med:.1f}%, n={len(_peer_sohs)} cells)."
                    f"</div>",
                    unsafe_allow_html=True,
                )
    except Exception:
        pass

    # ── Trajectory match warning ──────────────────────────────────────────────
    _render_trajectory_match_card(cell_id, df, trajectory_memory)

    # ── C4: Pin baseline ──────────────────────────────────────────────────────
    _pinned = st.session_state.get("pinned_cell")
    _pin_col1, _pin_col2 = st.columns([8, 2])
    with _pin_col2:
        if _pinned == cell_id:
            if st.button("📌 Unpin baseline", key=f"unpin_{cell_id}", use_container_width=True):
                import db as _db
                st.session_state["pinned_cell"] = None
                _db.set_setting("pinned_cell", None)
                st.rerun()
        else:
            if st.button("📌 Pin as baseline", key=f"pin_{cell_id}", use_container_width=True,
                         help="Pin this cell as a comparison baseline — all other cells show a delta rail."):
                import db as _db
                st.session_state["pinned_cell"] = cell_id
                _db.set_setting("pinned_cell", cell_id)
                st.rerun()
    if _pinned and _pinned != cell_id and _pinned in df.columns.__class__.__mro__[0].__mro__:
        pass  # comparison rail placeholder
    if _pinned and _pinned != cell_id:
        _pin_df_map = {k: v for k, v in st.session_state.items() if False}  # placeholder
        st.markdown(
            f"<div style='font-size:11px;color:#8896a8;margin:-6px 0 12px;padding:5px 12px;"
            f"background:#111827;border-radius:6px;border-left:3px solid #4a5568'>"
            f"Baseline: <strong style='color:#e2e8f0'>{_pinned}</strong> — navigate to that cell to compare."
            f"</div>",
            unsafe_allow_html=True,
        )

    # ── D6: Model confidence history ─────────────────────────────────────────
    if "soh_pct" in df.columns and "soh_pred" in df.columns:
        _conf_df = df[["cycle_number", "soh_pct", "soh_pred"]].dropna()
        if len(_conf_df) >= 20:
            with st.expander("Prediction confidence history", expanded=False):
                # Rolling absolute error as proxy for model confidence at each cycle window
                import numpy as _np_d6
                _err = (_conf_df["soh_pct"] - _conf_df["soh_pred"]).abs()
                _win = min(20, max(5, len(_conf_df) // 8))
                _roll_err = _err.rolling(_win, min_periods=3).mean()
                _cycles_d6 = _conf_df["cycle_number"].tolist()
                _err_vals  = _roll_err.tolist()
                _min_err   = float(_np_d6.nanmin(_err_vals)) if _err_vals else 0
                _max_err   = float(_np_d6.nanmax(_err_vals)) if _err_vals else 1
                _trend_dir = "improving" if _err_vals[-1] < _err_vals[0] else (
                    "stable" if abs(_err_vals[-1] - _err_vals[0]) < 0.5 else "diverging")
                _converged = _err_vals[-1] < 1.5 if _err_vals else False
                _interp = (
                    "Model has converged — error is low and stable. Confidence is high."
                    if _converged and _trend_dir in ("stable", "improving") else
                    "Model is still calibrating — wait for more cycles for tighter estimates."
                    if _trend_dir == "diverging" else
                    "Model confidence is improving as more data accumulates."
                )
                _fig_d6 = go.Figure()
                _fig_d6.add_trace(go.Scatter(
                    x=_cycles_d6, y=_err_vals,
                    mode="lines",
                    line=dict(color="#63b3ed", width=2),
                    name="Rolling MAE (SOH %)",
                    fill="tozeroy", fillcolor="rgba(99,179,237,0.08)",
                    hovertemplate="Cycle %{x}<br>Error: %{y:.2f}%<extra></extra>",
                ))
                _fig_d6.add_hline(y=1.5, line_dash="dot", line_color="#48bb78", line_width=1,
                                  annotation_text="Reliable", annotation_position="top right",
                                  annotation_font_color="#48bb78", annotation_font_size=10)
                _fig_d6.update_layout(
                    **base_layout(
                        height=180,
                        showlegend=False,
                        xaxis=dict(title="Cycle", zeroline=False),
                        yaxis=dict(title="Abs error (SOH %)",
                                   zeroline=False, range=[0, max(_max_err * 1.2, 3)]),
                    ),
                )
                st.plotly_chart(_fig_d6, use_container_width=True)
                st.caption(
                    f"Rolling {_win}-cycle mean absolute error between predicted and measured SOH. "
                    f"Trend: {_trend_dir}. {_interp}"
                )

    # ── 3 primary secondary metrics: RUL · Fade Rate · Resistance ────────────
    _fade_30 = float(latest["fade_rate_30cy"]) if "fade_rate_30cy" in latest.index else None
    _res_ohm = float(latest["resistance_ohm"]) if "resistance_ohm" in latest.index else None
    fade_display = f"{_fade_30 * 1000:.2f} mAh/cy" if _fade_30 is not None else "—"
    fade_sub     = "30-cycle rolling window" if _fade_30 is not None else "not available"
    res_display  = f"{_res_ohm * 1000:.1f} mΩ" if _res_ohm is not None else "—"
    res_sub      = "DC internal resistance" if _res_ohm is not None else "not available"
    months_chip_html = (
        f"<div class='metric-chip-sub' style='margin-top:2px'>"
        f"~{months_remaining:.0f} months · {rate_note}</div>"
        if months_remaining is not None else ""
    )

    _md_html(
        f"""<div class="metric-row" role="list" aria-label="Key performance metrics">
          <div class="metric-chip" role="listitem">
            <div class="metric-chip-label">Est. Remaining Life</div>
            <div class="metric-chip-value" aria-label="Estimated remaining life: {rul_display} {rul_sub}">{rul_display}</div>
            <div class="metric-chip-sub">{rul_sub}</div>
            {months_chip_html}
          </div>
          <div class="metric-chip" role="listitem">
            <div class="metric-chip-label">Fade Rate</div>
            <div class="metric-chip-value" style="font-size:20px" aria-label="Fade rate: {fade_display}">{fade_display}</div>
            <div class="metric-chip-sub">{fade_sub}</div>
          </div>
          <div class="metric-chip" role="listitem">
            <div class="metric-chip-label">Internal Resistance</div>
            <div class="metric-chip-value" style="font-size:20px" aria-label="Internal resistance: {res_display}">{res_display}</div>
            <div class="metric-chip-sub">{res_sub}</div>
          </div>
        </div>"""
    )

    # ── Cell Details expander: secondary metrics ──────────────────────────────
    sop_display = f"{sop_pct:.0f}%" if sop_pct is not None else "—"
    _cum_kwh    = float(latest["cumulative_kwh"]) if "cumulative_kwh" in latest.index else None
    kwh_display = f"{_cum_kwh:.2f} kWh" if _cum_kwh is not None else "—"
    _eq_cy      = float(latest["equivalent_cycles"]) if "equivalent_cycles" in latest.index and not pd.isna(latest["equivalent_cycles"]) else None
    eq_cy_display = f"{_eq_cy:,.0f}" if _eq_cy is not None else "—"
    eq_cy_sub   = "stress-normalized (CATL/BYD metric)" if _eq_cy is not None else "not available"
    _ce         = float(latest["coulombic_efficiency"]) if "coulombic_efficiency" in latest.index else None
    ce_display  = f"{_ce*100:.3f}%" if _ce is not None else "—"

    with st.expander("Cell Details", expanded=False):
        _md_html(
            f"""<div class="metric-row" role="list" aria-label="Cell detail metrics">
              <div class="metric-chip" role="listitem">
                <div class="metric-chip-label">State of Health</div>
                <div class="metric-chip-value">{current_soh:.1f}%</div>
                <div class="metric-chip-sub">vs 100% at cycle 1</div>
              </div>
              <div class="metric-chip" role="listitem">
                <div class="metric-chip-label">Cycles Completed</div>
                <div class="metric-chip-value">{current_cycle:,}</div>
                <div class="metric-chip-sub">charge / discharge</div>
              </div>
              <div class="metric-chip" role="listitem">
                <div class="metric-chip-label">Capacity Lost</div>
                <div class="metric-chip-value">{total_fade*1000:.0f} mAh</div>
                <div class="metric-chip-sub">since commissioning</div>
              </div>
              <div class="metric-chip" role="listitem">
                <div class="metric-chip-label">Peak Power (SoP)</div>
                <div class="metric-chip-value" style="font-size:20px">{sop_display}</div>
                <div class="metric-chip-sub">of initial capability</div>
              </div>
              <div class="metric-chip" role="listitem">
                <div class="metric-chip-label">Energy Delivered</div>
                <div class="metric-chip-value" style="font-size:18px">{kwh_display}</div>
                <div class="metric-chip-sub">cumulative throughput</div>
              </div>
              <div class="metric-chip" role="listitem">
                <div class="metric-chip-label">Equiv. Cycles</div>
                <div class="metric-chip-value" style="font-size:18px">{eq_cy_display}</div>
                <div class="metric-chip-sub">{eq_cy_sub}</div>
              </div>
              <div class="metric-chip" role="listitem">
                <div class="metric-chip-label">Coulombic Eff.</div>
                <div class="metric-chip-value" style="font-size:18px">{ce_display}</div>
                <div class="metric-chip-sub">last cycle Q_d / Q_c</div>
              </div>
            </div>"""
        )

    # ── Calendar Age Analysis ─────────────────────────────────────────────────
    if "cumulative_days" in df.columns:
        with st.expander("📅 Calendar Age Analysis", expanded=False):
            try:
                cal_last = float(df["cumulative_days"].iloc[-1])
                avg_rest = float(df["days_between_cycles"].mean()) if "days_between_cycles" in df.columns else 1.0
                total_fade_ah = float(df["capacity_ah"].iloc[0]) - float(df["capacity_ah"].iloc[-1])
                calendar_fade_pct = min(35, max(5, 100 * (cal_last * 0.00003 * 0.5) / max(total_fade_ah, 1e-6)))

                cal_c1, cal_c2, cal_c3 = st.columns(3)
                with cal_c1:
                    st.metric("Total Calendar Time", f"{cal_last:.0f} days", help="since first cycle")
                    st.markdown("<div style='font-size:11px;color:#8896a8;margin-top:-8px'>since first cycle</div>", unsafe_allow_html=True)
                with cal_c2:
                    st.metric("Avg Rest Between Cycles", f"{avg_rest:.1f} days", help="mean rest period")
                    st.markdown("<div style='font-size:11px;color:#8896a8;margin-top:-8px'>mean rest period</div>", unsafe_allow_html=True)
                with cal_c3:
                    st.metric("Calendar vs Cycle Fade", f"~{calendar_fade_pct:.0f}% calendar", help="remainder from cycling")
                    st.markdown("<div style='font-size:11px;color:#8896a8;margin-top:-8px'>remainder from cycling</div>", unsafe_allow_html=True)

                fig_cal = go.Figure()
                fig_cal.add_trace(go.Scatter(
                    x=_rdf["cycle_number"], y=_rdf["cumulative_days"],
                    name="Actual calendar time", line=dict(color="#63b3ed", width=2),
                    hovertemplate="Cycle %{x}: %{y:.1f} days<extra>Calendar</extra>",
                ))
                max_cy = int(df["cycle_number"].max())
                fig_cal.add_trace(go.Scatter(
                    x=[0, max_cy], y=[0, max_cy],
                    name="1 cycle/day baseline", line=dict(color="#4a5568", width=1.5, dash="dash"),
                    hoverinfo="skip",
                ))
                fig_cal.update_layout(
                    **base_layout(
                        height=260, legend=LEGEND_H,
                        xaxis=dict(title="Cycle", zeroline=False),
                        yaxis=dict(title="Days elapsed", zeroline=False),
                    ),
                )
                fig_cal.update_layout(title=dict(text="Calendar Time vs Cycle Count", font=dict(size=12, color="#a0aec0"), x=0))
                st.plotly_chart(fig_cal, use_container_width=True)
            except Exception as _e:
                st.info(f"Calendar age analysis unavailable: {_e}")

    st.markdown("<div style='height:8px'></div>", unsafe_allow_html=True)

    df_train = _rdf[_rdf["cycle_number"] <= split_cycle]
    df_test  = _rdf[_rdf["cycle_number"] >  split_cycle]

    fig = go.Figure()
    fig.add_trace(go.Scatter(
        x=_rdf["cycle_number"], y=_rdf["soh_pct"],
        name="Actual SOH", line=dict(color="#3a4a5e", width=1), mode="lines",
        hovertemplate="Cycle %{x}: %{y:.1f}%<extra>Actual</extra>",
    ))
    fig.add_trace(go.Scatter(
        x=_rdf["cycle_number"], y=_rdf["soh_rolling_avg"],
        name="10-cycle avg", line=dict(color="#63b3ed", width=2), mode="lines",
        hovertemplate="Cycle %{x}: %{y:.1f}%<extra>10-cy avg</extra>",
    ))
    fig.add_trace(go.Scatter(
        x=df_test["cycle_number"], y=df_test["soh_pred"],
        name="Model (test)", line=dict(color="#48bb78", width=2, dash="dot"), mode="lines",
        hovertemplate="Cycle %{x}: %{y:.1f}%<extra>Model</extra>",
    ))
    # F2: ±σ confidence band derived from leave-cell-out residuals
    if len(df_test) >= 5 and "soh_pred" in df_test.columns:
        import numpy as _np_f2
        _f2_valid = df_test[["cycle_number", "soh_pct", "soh_pred"]].dropna()
        if len(_f2_valid) >= 3:
            _sigma_f2 = float((_f2_valid["soh_pct"] - _f2_valid["soh_pred"]).std())
            _sigma_f2 = max(min(_sigma_f2, 8.0), 0.3)
            _cx_f2  = _f2_valid["cycle_number"].tolist()
            _cu_f2  = (_f2_valid["soh_pred"] + _sigma_f2).clip(upper=102.0).tolist()
            _cl_f2  = (_f2_valid["soh_pred"] - _sigma_f2).clip(lower=60.0).tolist()
            fig.add_trace(go.Scatter(
                x=_cx_f2 + _cx_f2[::-1],
                y=_cu_f2 + _cl_f2[::-1],
                fill="toself",
                fillcolor="rgba(72,187,120,0.10)",
                line=dict(width=0),
                name=f"±{_sigma_f2:.1f}% model uncertainty (σ)",
                hoverinfo="skip",
            ))
    fig.add_vline(
        x=split_cycle, line_dash="dot", line_color="#4a5568", line_width=1,
        annotation_text=f"Train → Test (cy {split_cycle})",
        annotation_position="top left",
        annotation_font_color="#4a5568", annotation_font_size=11,
    )
    # ── Scenario projections ──
    import numpy as np
    last_cycle = df["cycle_number"].iloc[-1]
    last_soh   = df["soh_pct"].iloc[-1]
    eol_line   = float(st.session_state.get("eol_threshold_pct", 80.0))
    nominal_rate    = float(df["fade_rate_50cy"].iloc[-1]) * 100   # % SOH / cycle
    optimistic_rate = nominal_rate * 0.6
    pessimistic_rate = nominal_rate * 1.5

    def _proj(rate):
        if rate > 1e-9:
            n_steps = min(500, int((last_soh - eol_line) / rate) + 10)
        else:
            n_steps = 200
        n_steps = max(n_steps, 2)
        proj_cycles = np.arange(last_cycle, last_cycle + n_steps)
        proj_soh    = last_soh - rate * np.arange(n_steps)
        proj_soh    = np.clip(proj_soh, 60.0, None)
        return proj_cycles.tolist(), proj_soh.tolist()

    for rate, name, color in [
        (nominal_rate,     "Nominal projection",          "#63b3ed"),
        (optimistic_rate,  "Optimistic (−40% stress)",    "#48bb78"),
        (pessimistic_rate, "Pessimistic (+50% stress)",   "#fc8181"),
    ]:
        px, py = _proj(rate)
        fig.add_trace(go.Scatter(
            x=px, y=py, name=name, mode="lines",
            line=dict(dash="dash", width=1.5, color=color),
            opacity=0.7,
            hovertemplate="Cycle %{x}: %{y:.1f}%<extra>" + name + "</extra>",
        ))

    fig.add_hline(
        y=eol_line, line_dash="dot", line_color="#e53e3e", line_width=1,
        annotation_text=f"EOL threshold ({eol_line:.0f}%)",
        annotation_position="bottom right",
    )
    y_min = max(df["soh_pct"].min() - 2, 60)
    fig.update_layout(
        **base_layout(
            height=340, legend=LEGEND_H,
            xaxis=dict(title="Cycle", zeroline=False),
            yaxis=dict(title="SOH %",
                       zeroline=False, range=[y_min, 101]),
        ),
    )
    st.plotly_chart(fig, use_container_width=True)
    _ov_prov = _cell_provenance(cell_id)
    if cell_id.startswith("S-"):
        _ov_caption = "Capacity data: ● MEASURED (Severson 2019, Nature Energy). Projections: ◐ SIMULATED (linear extrapolation)."
    elif _ov_prov == "measured":
        _ov_caption = "Capacity data: ● MEASURED (NASA PCoE). Projections: ◐ SIMULATED (linear extrapolation)."
    else:
        _ov_caption = "All data: ○ SYNTHETIC — no physical measurements underlie any value."
    st.caption(
        "Projections assume constant fade rate. Optimistic = 40% stress reduction. Pessimistic = 50% stress increase. "
        + _ov_caption
    )


# ---------------------------------------------------------------------------
# Page: Health
# ---------------------------------------------------------------------------

def page_health(df: pd.DataFrame, split_cycle: int, cell_id: str,
                bundle: dict = None, rul_reliable: bool = True):
    _action_bar("health")
    st.markdown(f"# What is degrading {cell_id}?")
    _rdf = _resample_df(df)   # downsampled for charts; df still used for latest/masks

    # ── Data provenance declaration ──────────────────────────────────────────
    _cp = _cell_provenance(cell_id)
    if cell_id.startswith("S-"):
        _prov_detail = (
            f"Capacity and resistance data for <strong>{cell_id}</strong> are real measurements "
            f"from the Severson 2019 LFP dataset (Nature Energy, 2019). "
            f"Derived analyses (Resistance Component Proxy, rate capability) use physics models "
            f"applied to these measurements and are labelled ◐ SIMULATED individually. "
            f"dQ/dV analysis is not shown — the LiCoO₂ simulation is not applicable to LFP chemistry."
        )
    elif _cp == "measured":
        _prov_detail = (
            f"Capacity and resistance data for <strong>{cell_id}</strong> are real measurements "
            f"from the NASA PCoE Battery Aging Dataset (Saha &amp; Goebel, 2007). "
            f"Derived analyses (Resistance Proxy, dQ/dV, rate capability) use physics models applied to "
            f"these measurements and are labelled ◐ SIMULATED individually."
        )
    else:
        _prov_detail = (
            f"<strong>{cell_id}</strong> is a physics-informed synthetic cell generated by "
            f"<code>generate_cell_data()</code> — no physical measurements underlie any value "
            f"on this page. All analyses are labelled ○ SYNTHETIC. "
            f"<strong>Do not use synthetic cell outputs for real engineering decisions.</strong>"
        )
    _md_html(provenance_banner(_cp, _prov_detail))

    # ── Chemistry inline indicator ────────────────────────────────────────────
    _chem_label = {
        "severson":  "LFP · Lithium Iron Phosphate (Severson 2019)",
        "nasa":      "LiCoO₂ NCA · Lithium Cobalt Oxide (NASA PCoE)",
        "synthetic": "LiCoO₂ · Lithium Cobalt Oxide (synthetic)",
        "uploaded":  "User-defined chemistry",
    }.get(st.session_state.get("data_mode", "synthetic"), "LiCoO₂")
    st.markdown(
        f"<div style='display:flex;align-items:center;gap:8px;margin-bottom:12px'>"
        f"<span style='font-size:10px;font-weight:700;background:#2d374899;"
        f"border:1px solid #4a5568;color:#a0aec0;padding:2px 9px;border-radius:6px;"
        f"letter-spacing:0.06em'>CHEMISTRY</span>"
        f"<span style='font-size:13px;color:#a0aec0'>{_chem_label}</span>"
        f"</div>",
        unsafe_allow_html=True,
    )

    latest = df.iloc[-1]
    current_soh = latest["soh_pct"]
    status_label, status_colour = soh_status(current_soh)

    # Knee-point detection
    knee = detect_knee(df["soh_pct"], df["cycle_number"])
    sop_pct = float(latest["sop_pct"]) if "sop_pct" in latest.index else None

    knee_note = ""
    if knee["detected"]:
        k_cy  = knee["cycle"]
        k_soh = knee["soh_at_knee"]
        cur   = int(latest["cycle_number"])
        if cur >= k_cy:
            knee_note = f"· ⚡ Knee at cycle {k_cy} ({k_soh:.1f}% SOH) — now in accelerating phase"
        else:
            knee_note = f"· Knee projected ~cycle {k_cy} ({k_soh:.1f}% SOH)"

    _md_html(
        f"""
        <div class="hero-card">
            <div class="hero-label">Health Assessment · {cell_id}</div>
            <div class="hero-value {status_colour}">{current_soh:.1f}% SOH</div>
            <div class="hero-sub">
                Fading at ~{latest['fade_rate_50cy']*1000:.2f} mAh/cycle (50-cycle avg)
                &nbsp;·&nbsp; Internal resistance: {latest.get('resistance_ohm',0):.3f} Ω
                &nbsp;·&nbsp; Peak power: {f"{sop_pct:.0f}% of initial" if sop_pct else "—"}
                {knee_note}
            </div>
        </div>
        """
    )

    # ── C4: Pin baseline (Health page) ───────────────────────────────────────
    _h_pinned = st.session_state.get("pinned_cell")
    _h_pc2 = st.columns([8, 2])[1]
    with _h_pc2:
        if _h_pinned == cell_id:
            if st.button("📌 Unpin baseline", key=f"unpin_h_{cell_id}", use_container_width=True):
                import db as _db
                st.session_state["pinned_cell"] = None
                _db.set_setting("pinned_cell", None)
                st.rerun()
        else:
            if st.button("📌 Pin as baseline", key=f"pin_h_{cell_id}", use_container_width=True,
                         help="Pin this cell as comparison baseline"):
                import db as _db
                st.session_state["pinned_cell"] = cell_id
                _db.set_setting("pinned_cell", cell_id)
                st.rerun()

    col1, col2 = st.columns(2)

    # Anomaly cycles (precompute for both charts)
    cap_anomalies = df[df.get("capacity_anomaly", pd.Series(False, index=df.index))] if "capacity_anomaly" in df.columns else df.iloc[0:0]
    res_anomalies = df[df.get("resistance_anomaly", pd.Series(False, index=df.index))] if "resistance_anomaly" in df.columns else df.iloc[0:0]

    with col1:
        st.markdown("<div style='height:4px'></div>", unsafe_allow_html=True)
        fig = go.Figure()
        fig.add_trace(go.Scatter(
            x=_rdf["cycle_number"], y=_rdf["capacity_fade_ah"] * 1000,
            fill="tozeroy", fillcolor="rgba(252,129,129,0.08)",
            line=dict(color="#fc8181", width=2),
            hovertemplate="Cycle %{x}: %{y:.1f} mAh lost<extra></extra>",
            showlegend=False,
        ))
        if len(cap_anomalies) > 0:
            fig.add_trace(go.Scatter(
                x=cap_anomalies["cycle_number"],
                y=cap_anomalies["capacity_fade_ah"] * 1000,
                mode="markers", name=f"Anomaly ({len(cap_anomalies)})",
                marker=dict(color="#f6ad55", size=7, symbol="diamond",
                            line=dict(color="#1a202c", width=1)),
                hovertemplate="Cycle %{x}: anomalous capacity<extra>⚠ Anomaly</extra>",
            ))
        if knee["detected"]:
            fig.add_vline(x=knee["cycle"], line=dict(color="#9f7aea", width=1.5, dash="dot"),
                          annotation_text=f"Knee ({knee['cycle']})",
                          annotation=dict(font=dict(size=9, color="#9f7aea")))
        fig.update_layout(
            height=280,
            **base_layout(
                legend=LEGEND_H,
                xaxis=dict(title="Cycle", zeroline=False),
                yaxis=dict(title="mAh lost", zeroline=False),
            ),
        )
        st.plotly_chart(fig, use_container_width=True)

    with col2:
        st.markdown("<div style='height:4px'></div>", unsafe_allow_html=True)
        fig2 = go.Figure()
        fig2.add_trace(go.Scatter(
            x=_rdf["cycle_number"], y=_rdf["resistance_ohm"] * 1000,
            line=dict(color="#4a5568", width=1), name="Raw",
            hovertemplate="Cycle %{x}: %{y:.1f} mΩ<extra></extra>",
        ))
        fig2.add_trace(go.Scatter(
            x=_rdf["cycle_number"],
            y=_rdf["resistance_ohm"].rolling(30, min_periods=1).mean() * 1000,
            name="30-cycle avg", line=dict(color="#f6ad55", width=2),
            hovertemplate="Cycle %{x}: %{y:.1f} mΩ<extra>30-cy avg</extra>",
        ))
        if len(res_anomalies) > 0:
            fig2.add_trace(go.Scatter(
                x=res_anomalies["cycle_number"],
                y=res_anomalies["resistance_ohm"] * 1000,
                mode="markers", name=f"Spike ({len(res_anomalies)})",
                marker=dict(color="#fc8181", size=7, symbol="diamond",
                            line=dict(color="#1a202c", width=1)),
                hovertemplate="Cycle %{x}: resistance spike<extra>⚠ Spike</extra>",
            ))
        fig2.update_layout(
            **base_layout(
                height=280, legend=LEGEND_H,
                xaxis=dict(title="Cycle", zeroline=False),
                yaxis=dict(title="mΩ", zeroline=False),
            ),
        )
        st.plotly_chart(fig2, use_container_width=True)

    # ── Section 2: Mechanism (always visible) ───────────────────────────────
    _mech_v, _mech_c, _mech_icon = "Insufficient data", "#718096", "○"
    try:
        import numpy as _np_ms
        _ms = {}
        if "coulombic_efficiency" in df.columns:
            _ce_v2 = df[["cycle_number", "coulombic_efficiency"]].dropna()
            if len(_ce_v2) >= 10:
                _ms["ce_slope"] = float(_np_ms.polyfit(
                    _ce_v2["cycle_number"].values.astype(float),
                    _ce_v2["coulombic_efficiency"].values, 1)[0])
        if "soh_pct" in df.columns:
            _sv2 = df[["cycle_number", "soh_pct"]].dropna()
            if len(_sv2) >= 20:
                _cy2 = _sv2["cycle_number"].values.astype(float)
                _cy2n = (_cy2 - _cy2.min()) / max(_cy2.max() - _cy2.min(), 1)
                _ms["nonlin"] = float(_np_ms.polyfit(_cy2n, _sv2["soh_pct"].values, 2)[0])
        if "resistance_normalized" in df.columns:
            _rv2 = df[["cycle_number", "resistance_normalized"]].dropna()
            if len(_rv2) >= 10:
                _ms["r_slope"] = float(_np_ms.polyfit(
                    _rv2["cycle_number"].values.astype(float),
                    _rv2["resistance_normalized"].values, 1)[0]) * 1000
        _lli2, _lam2 = 0, 0
        if _ms.get("ce_slope", 0) < -1e-6: _lli2 += 3
        if _ms.get("nonlin", 0) < -0.5: _lam2 += 3
        elif _ms.get("nonlin", 0) > 0.5: _lli2 += 1
        if _ms.get("r_slope", 0) > 0.02: _lam2 += 2
        elif 0.005 < _ms.get("r_slope", 0) <= 0.02: _lli2 += 1
        if _lli2 + _lam2 == 0:
            _mech_v, _mech_c, _mech_icon = "Insufficient data", "#718096", "○"
        elif _lli2 > _lam2 * 1.5:
            _mech_v, _mech_c, _mech_icon = "LLI — Loss of Lithium Inventory", "#f6ad55", "◑"
        elif _lam2 > _lli2 * 1.5:
            _mech_v, _mech_c, _mech_icon = "LAM — Loss of Active Material", "#fc8181", "◕"
        else:
            _mech_v, _mech_c, _mech_icon = "Mixed LLI + LAM", "#b794f4", "●"
    except Exception:
        pass

    # ── E1: 12-month SOH trajectory forecast with uncertainty cone ──────────────
    st.markdown("<div class='section-header'>12-Month SOH Forecast</div>", unsafe_allow_html=True)
    import numpy as _np_e1
    _e1_last_cycle = int(df["cycle_number"].iloc[-1])
    _e1_last_soh   = float(df["soh_pct"].iloc[-1])
    _e1_fade_30    = float(latest.get("fade_rate_30cy", 0.0)) * 100   # % per cycle
    _e1_fade_acc   = 0.0
    if "fade_rate_30cy" in df.columns and len(df) >= 60:
        _e1_f1 = float(df["fade_rate_30cy"].iloc[-30:].mean()) * 100
        _e1_f0 = float(df["fade_rate_30cy"].iloc[-60:-30].mean()) * 100
        _e1_fade_acc = max(0.0, _e1_f1 - _e1_f0) / 30  # % SOH / cycle² acceleration
    _e1_cpd = float(st.session_state.get("cycles_per_day", 1.0))
    _CYCLES_12M    = int(365 * _e1_cpd)
    _e1_q10        = float(df["rul_q10"].iloc[-1]) if "rul_q10" in df.columns else None
    _e1_q90        = float(df["rul_q90"].iloc[-1]) if "rul_q90" in df.columns else None
    _e1_eol        = float(st.session_state.get("eol_threshold_pct", 80.0))

    # Reduced C-rate scenario: stress model says C-rate^0.7 factor
    _e1_crate_prof = CELL_STRESS_PROFILES.get(cell_id, {}).get("c_rate", 1.0)
    _e1_reduced    = max(0.1, _e1_crate_prof - 0.5)
    _e1_stress_ratio = (_e1_reduced / _e1_crate_prof) ** 0.7 if _e1_crate_prof > 0.1 else 1.0
    _e1_fade_reduced = _e1_fade_30 * _e1_stress_ratio

    def _e1_proj(fade_base, accel, n_cycles):
        cycles = _np_e1.arange(1, n_cycles + 1)
        soh    = _e1_last_soh - fade_base * cycles - 0.5 * accel * cycles**2
        return (_e1_last_cycle + cycles).tolist(), _np_e1.clip(soh, _e1_eol - 10, 102).tolist()

    _e1_cx,  _e1_cy  = _e1_proj(_e1_fade_30, _e1_fade_acc, _CYCLES_12M)
    _e1_rx,  _e1_ry  = _e1_proj(_e1_fade_reduced, _e1_fade_acc * _e1_stress_ratio, _CYCLES_12M)

    # Uncertainty cone from Q10/Q90 if available, else ±25% fade
    _e1_fade_lo = _e1_fade_30 * 0.75
    _e1_fade_hi = _e1_fade_30 * 1.35 + _e1_fade_acc * _CYCLES_12M * 0.5
    _e1_ux, _e1_uy_lo = _e1_proj(_e1_fade_lo, 0, _CYCLES_12M)
    _e1_ux, _e1_uy_hi = _e1_proj(_e1_fade_hi, _e1_fade_acc, _CYCLES_12M)

    _fig_e1 = go.Figure()
    # Historical SOH
    _e1_hist = df[["cycle_number", "soh_pct"]].tail(100)
    _fig_e1.add_trace(go.Scatter(
        x=_e1_hist["cycle_number"].tolist(), y=_e1_hist["soh_pct"].tolist(),
        name="Actual SOH", line=dict(color="#63b3ed", width=2), mode="lines",
        hovertemplate="Cycle %{x}: %{y:.1f}%<extra>Actual</extra>",
    ))
    # Uncertainty cone (filled band)
    _fig_e1.add_trace(go.Scatter(
        x=_e1_ux + _e1_ux[::-1],
        y=_e1_uy_hi + _e1_uy_lo[::-1],
        fill="toself", fillcolor="rgba(99,179,237,0.10)", line=dict(width=0),
        name="Uncertainty cone", hoverinfo="skip",
    ))
    # Base forecast (current C-rate)
    _fig_e1.add_trace(go.Scatter(
        x=_e1_cx, y=_e1_cy, name=f"Forecast (current {_e1_crate_prof:.1f}C)",
        line=dict(color="#63b3ed", width=2, dash="dash"), mode="lines",
        hovertemplate="Cycle %{x}: %{y:.1f}%<extra>Forecast</extra>",
    ))
    # Reduced C-rate scenario
    _fig_e1.add_trace(go.Scatter(
        x=_e1_rx, y=_e1_ry, name=f"Reduced C-rate ({_e1_reduced:.1f}C)",
        line=dict(color="#48bb78", width=2, dash="dot"), mode="lines",
        hovertemplate="Cycle %{x}: %{y:.1f}%<extra>Reduced C-rate</extra>",
    ))
    _fig_e1.add_hline(y=_e1_eol, line_dash="dot", line_color="#e53e3e", line_width=1,
                      annotation_text=f"EOL ({_e1_eol:.0f}%)", annotation_position="bottom right",
                      annotation_font_color="#e53e3e", annotation_font_size=10)
    _fig_e1.add_vline(x=_e1_last_cycle, line_dash="dot", line_color="#4a5568", line_width=1,
                      annotation_text="Now", annotation_position="top left",
                      annotation_font_color="#4a5568", annotation_font_size=10)
    _fig_e1.update_layout(
        **base_layout(
            height=300, legend=LEGEND_H,
            xaxis=dict(title="Cycle", zeroline=False),
            yaxis=dict(title="SOH %",
                       zeroline=False, range=[max(_e1_eol - 8, 55), 102]),
        ),
    )
    st.plotly_chart(_fig_e1, use_container_width=True)
    # Plain-English summary
    _e1_soh_12m   = max(_e1_eol - 2, _e1_last_soh - _e1_fade_30 * _CYCLES_12M - 0.5 * _e1_fade_acc * _CYCLES_12M**2)
    _e1_soh_12m_r = max(_e1_eol - 2, _e1_last_soh - _e1_fade_reduced * _CYCLES_12M)
    _e1_gain      = _e1_soh_12m_r - _e1_soh_12m
    _e1_txt       = (
        f"At current C-rate ({_e1_crate_prof:.1f}C), projected SOH in 12 months: "
        f"<strong style='color:#63b3ed'>{_e1_soh_12m:.1f}%</strong>. "
        + (f"Reducing to {_e1_reduced:.1f}C could preserve an additional "
           f"<strong style='color:#48bb78'>{_e1_gain:.1f}% SOH</strong> "
           f"({_e1_soh_12m_r:.1f}% projected)." if _e1_gain > 0.1 else "")
        + f" Uncertainty cone: ±25–35% fade variability. ◐ SIMULATED — linear extrapolation."
    )
    _md_html(f"<div style='font-size:12px;color:#a0aec0;padding:4px 0 16px;line-height:1.6'>{_e1_txt}</div>")

    _mc_left, _mc_right = st.columns([3, 2])
    with _mc_left:
        _md_html(
            f"<div style='background:#1e2a38;border:1px solid #2d3748;border-radius:10px;"
            f"padding:14px 20px;display:flex;align-items:center;gap:12px'>"
            f"<span style='font-size:22px'>{_mech_icon}</span>"
            f"<div>"
            f"<div style='font-size:10px;color:#4a5568;text-transform:uppercase;"
            f"letter-spacing:0.1em;margin-bottom:2px'>Degradation Mechanism</div>"
            f"<div style='font-size:15px;font-weight:700;color:{_mech_c}'>{_mech_v}</div>"
            f"</div></div>"
        )

    # ── Section 3: Action (always visible) ──────────────────────────────────
    with _mc_right:
        try:
            from recommendations import classify as _rec_classify
            from consequences import application_fit as _app_fit
            _lat_h  = df.iloc[-1]
            _soh_h  = float(_lat_h["soh_pct"])
            _f30_h  = float(_lat_h.get("fade_rate_30cy", 0.0))
            _f50_h  = float(_lat_h.get("fade_rate_50cy", 0.0))
            _rul_h  = float(_lat_h.get("rul_pred")) if (rul_reliable and _lat_h.get("rul_pred") is not None) else None
            _fit_h  = _app_fit(_soh_h, _f30_h, None)
            _rec_h  = _rec_classify(_soh_h, _f30_h, _f50_h, rul_reliable, _rul_h, _fit_h)
            _al_h, _ac_h, _abg_h = ACTION_META[_rec_h["action"]]
            _cc_h, _cl_h = CONF_META[_rec_h["confidence"]]
            _md_html(
                f"<div style='background:{_abg_h};border:2px solid {_ac_h}55;border-radius:10px;"
                f"padding:14px 20px'>"
                f"<div style='font-size:10px;font-weight:700;color:{_ac_h}99;"
                f"text-transform:uppercase;letter-spacing:0.1em;margin-bottom:4px'>Recommended Action</div>"
                f"<div style='font-size:18px;font-weight:800;color:{_ac_h}'>{_al_h}</div>"
                f"<div style='margin-top:6px'>"
                f"<span style='background:{_cc_h}22;border:1px solid {_cc_h}55;color:{_cc_h};"
                f"font-size:10px;font-weight:700;padding:2px 8px;border-radius:8px'>{_cl_h}</span>"
                f"</div></div>"
            )
            if st.button("Full decision analysis →", key=f"h_to_dec_{cell_id}", use_container_width=True):
                st.session_state.page = "decision"
                st.rerun()
        except Exception:
            pass

    # ── Engineering Details toggle ───────────────────────────────────────────
    st.markdown("<div style='height:8px'></div>", unsafe_allow_html=True)
    _default_eng = st.session_state.get("user_role", "Engineer") == "Engineer"
    _show_eng = st.checkbox(
        "Engineering details",
        key=f"health_eng_{cell_id}",
        value=_default_eng,
        help="Fade rate analysis, dQ/dV, resistance model, PyBaMM projection, and all diagnostic expanders.",
    )
    if not _show_eng:
        return

    # ── Fade acceleration detection (compute before fig3 so we can annotate it) ──
    # Heuristic: first cycle after cycle 30 where the 30-cycle rolling fade rate
    # exceeds 2× the mean rate from cycles 1–30. Not triggered in first 30 cycles
    # because early fade rates are noisy while rolling features stabilise.
    INFLECTION_MIN_CYCLE = 30
    ACCEL_FACTOR         = 2.0
    first_accel: int | None = None

    if "fade_rate_30cy" in df.columns:
        df_baseline = df[df["cycle_number"] <= INFLECTION_MIN_CYCLE]
        df_post30   = df[df["cycle_number"] >  INFLECTION_MIN_CYCLE]
        if len(df_baseline) > 0:
            baseline_rate = df_baseline["fade_rate_30cy"].mean()
            if baseline_rate > 0 and not pd.isna(baseline_rate):
                accel_threshold = baseline_rate * ACCEL_FACTOR
                accel_rows = df_post30[df_post30["fade_rate_30cy"] > accel_threshold]
                if len(accel_rows) > 0:
                    first_accel = int(accel_rows["cycle_number"].iloc[0])

    st.markdown(
        "<div class='section-header'>Fade Rate — Is degradation accelerating?</div>",
        unsafe_allow_html=True,
    )
    fig3 = go.Figure()
    fig3.add_trace(go.Scatter(
        x=_rdf["cycle_number"], y=_rdf["fade_rate_10cy"] * 1000,
        line=dict(color="#4a5568", width=1), name="10-cycle window",
    ))
    fig3.add_trace(go.Scatter(
        x=_rdf["cycle_number"], y=_rdf["fade_rate_30cy"] * 1000,
        line=dict(color="#63b3ed", width=2), name="30-cycle window",
    ))
    fig3.add_trace(go.Scatter(
        x=_rdf["cycle_number"], y=_rdf["fade_rate_50cy"] * 1000,
        line=dict(color="#48bb78", width=2), name="50-cycle window",
    ))
    if first_accel is not None:
        fig3.add_vline(
            x=first_accel,
            line=dict(color="#fc8181", width=1.5, dash="dash"),
            annotation_text=f"Fade acceleration threshold: {ACCEL_FACTOR:.0f}× {INFLECTION_MIN_CYCLE}-cycle baseline (heuristic)",
            annotation_position="top right",
            annotation=dict(font=dict(size=10, color="#fc8181"), bgcolor="rgba(26,32,44,0.85)"),
        )
    if knee["detected"]:
        fig3.add_vline(
            x=knee["cycle"],
            line=dict(color="#9f7aea", width=1.5, dash="dot"),
            annotation_text=f"Knee-point ({knee['cycle']})",
            annotation_position="top left",
            annotation=dict(font=dict(size=10, color="#9f7aea"), bgcolor="rgba(26,32,44,0.85)"),
        )
    fig3.update_layout(
        **base_layout(
            height=280, legend=LEGEND_H,
            xaxis=dict(title="Cycle", zeroline=False),
            yaxis=dict(title="mAh lost per cycle", zeroline=False),
        ),
    )
    st.plotly_chart(fig3, use_container_width=True)

    if first_accel is not None:
        st.markdown(
            f"<div style='background:rgba(252,129,129,0.08);border:1px solid rgba(252,129,129,0.3);"
            f"border-radius:8px;padding:12px 16px;font-size:12px;color:#fed7d7;margin-top:-8px'>"
            f"⚠ <strong>Fade acceleration detected at cycle {first_accel}</strong> — "
            f"30-cycle rolling rate exceeded {ACCEL_FACTOR:.0f}× the cycle-1–{INFLECTION_MIN_CYCLE} baseline. "
            f"Schedule inspection or monitor closely."
            f"</div>",
            unsafe_allow_html=True,
        )

    early = df[df["confidence_tag"] == "Calibrating"]
    if len(early) > 0:
        st.info(
            f"**Calibrating** — the first {len(early)} cycles show higher variability "
            f"while rolling-window features stabilise. Readings from cycle 50 onward are reliable."
        )

    # ── Anomaly summary ──

    n_cap_anom = len(cap_anomalies)
    n_res_anom = len(res_anomalies)
    if n_cap_anom > 0 or n_res_anom > 0:
        st.markdown(
            f"<div style='background:rgba(246,173,85,0.08);border:1px solid rgba(246,173,85,0.3);"
            f"border-radius:8px;padding:12px 16px;font-size:12px;color:#fefcbf;margin-top:8px'>"
            f"⚠ <strong>Anomalous cycles detected</strong> — "
            f"{n_cap_anom} capacity outlier(s) · {n_res_anom} resistance spike(s) "
            f"(>2.5σ from 30-cycle rolling baseline). "
            f"Isolated anomalies are often measurement noise. Clustered anomalies may indicate "
            f"lithium plating, electrolyte leakage, or tab resistance changes."
            f"</div>",
            unsafe_allow_html=True,
        )

    # ── Degradation phase summary ──
    st.markdown("<div class='section-header'>Degradation Phase Analysis</div>", unsafe_allow_html=True)
    phase_labels = degradation_phases(df["soh_pct"], df["cycle_number"])
    phase_counts = phase_labels.value_counts()
    n_early = int(phase_counts.get("Early", 0))
    n_plateau = int(phase_counts.get("Plateau", 0))
    n_accel = int(phase_counts.get("Accelerating", 0))
    current_phase = knee["phase"]
    PHASE_COLOUR = {"Early": "#63b3ed", "Plateau": "#48bb78", "Accelerating": "#fc8181", "Unknown": "#4a5568"}
    pc = PHASE_COLOUR.get(current_phase, "#4a5568")

    _md_html(
        f"""
        <div style="background:#1e2a38;border:1px solid #2d3748;border-radius:10px;padding:18px 22px;margin-bottom:16px">
            <div style="display:flex;gap:32px;flex-wrap:wrap;align-items:flex-start">
                <div>
                    <div style="font-size:11px;color:#4a5568;text-transform:uppercase;letter-spacing:0.07em">Current phase</div>
                    <div style="font-size:26px;font-weight:700;color:{pc}">{current_phase}</div>
                    <div style="font-size:11px;color:#4a5568;margin-top:2px">
                        {"Knee at cycle " + str(knee["cycle"]) + f" ({knee['soh_at_knee']}% SOH)" if knee["detected"] else "No knee detected yet"}
                    </div>
                </div>
                <div style="border-left:1px solid #2d3748;padding-left:24px">
                    <div style="font-size:11px;color:#4a5568;margin-bottom:8px;text-transform:uppercase;letter-spacing:0.07em">Cycle breakdown</div>
                    <div style="font-size:12px;color:#a0aec0;line-height:2">
                        <span style="color:#63b3ed">Early</span> — {n_early} cycles (rolling features stabilising)<br>
                        <span style="color:#48bb78">Plateau</span> — {n_plateau} cycles (linear degradation regime)<br>
                        <span style="color:#fc8181">Accelerating</span> — {n_accel} cycles (post-knee, rapid fade)
                    </div>
                </div>
                <div style="border-left:1px solid #2d3748;padding-left:24px;max-width:280px">
                    <div style="font-size:11px;color:#4a5568;margin-bottom:6px;text-transform:uppercase;letter-spacing:0.07em">What this means</div>
                    <div style="font-size:11px;color:#8896a8;line-height:1.7">
                        {"The cell is past its knee point — degradation has entered the rapid-fade regime. "
                         "Remaining life estimates are shorter and less predictable than in the plateau phase. "
                         "Prioritise replacement planning."
                         if current_phase == "Accelerating" else
                         "The cell is in the stable plateau phase — degradation is approximately linear "
                         "and predictable. RUL estimates are most reliable here."
                         if current_phase == "Plateau" else
                         "Early cycles — rolling-window features are still stabilising. "
                         "Fade rate estimates will become reliable from cycle 50 onward."}
                    </div>
                </div>
            </div>
        </div>
        """
    )

    # ── H4: Data Lineage ─────────────────────────────────────────────────────
    with st.expander("🔍 Data Lineage — Trace Any Value to Source Cycles", expanded=False):
        _lineage_rows = []
        _col_map = {
            "soh_pct":              ("SOH %",                "measured capacity / initial capacity × 100",        "Derived from measured capacity_ah"),
            "capacity_ah":          ("Capacity (Ah)",         "raw discharge capacity per cycle",                  "Direct measurement from cycler"),
            "fade_rate_30cy":       ("Fade Rate (30cy)",      "ΔQ / Δcycle over rolling 30-cycle window",          "Derived: pandas rolling().apply()"),
            "coulombic_efficiency": ("Coulombic Efficiency",  "Q_discharge / Q_charge per cycle",                  "Direct measurement from cycler"),
            "resistance_normalized":("Resistance (norm.)",    "R(n) / R(1) — normalised internal resistance",      "Derived from voltage step at cycle start"),
            "rul_pred":             ("RUL Prediction",        "GBRT model output (leave-cell-out validated)",       "ML model: GradientBoostingRegressor"),
            "ce_rolling_30cy":      ("CE Rolling (30cy)",     "30-cycle rolling mean of coulombic_efficiency",      "Derived: pandas rolling().mean()"),
            "dqdv_peak_value":      ("dQ/dV Peak Value",      "simulated via LiCoO₂ OCV polynomial model",         "Simulated: simulate_vq_curve()"),
            "sop_pct":              ("SOP %",                 "State of Power — rate capability proxy",            "Derived from R_normalized"),
            "c_rate_rolling_10cy":  ("C-rate (10cy avg)",     "charge/discharge rate (A / nominal Ah), 10-cy mean", "Protocol constant (NASA) or synthetic profile"),
            "stress_index":         ("Stress Index",          "Arrhenius(T) × C-rate^0.7 — composite aging driver", "Derived: features.build_features()"),
            "dod_proxy":            ("DoD proxy",             "capacity(n) / capacity(1) — depth of discharge",    "Derived from measured capacity_ah"),
        }
        for _col, (_label, _formula, _source) in _col_map.items():
            _avail = _col in df.columns
            _latest_val = f"{df[_col].iloc[-1]:.4f}" if _avail and df[_col].notna().any() else "—"
            _n_valid = int(df[_col].notna().sum()) if _avail else 0
            _lineage_rows.append({
                "Metric": _label,
                "Latest value": _latest_val,
                "Valid cycles": _n_valid if _avail else "—",
                "Formula / derivation": _formula,
                "Source": _source,
            })
        _lin_df = pd.DataFrame(_lineage_rows)
        st.dataframe(_lin_df, use_container_width=True, hide_index=True)
        st.caption(
            f"Cell: {cell_id} · {len(df)} total cycles · "
            f"First cycle: {int(df['cycle_number'].iloc[0])} · "
            f"Last cycle: {int(df['cycle_number'].iloc[-1])} · "
            f"Data provenance: {_cell_provenance(cell_id).upper()}"
        )

    # ── H5: Tier 2 — Evidence layer ─────────────────────────────────────────
    _md_html(
        "<div style='font-size:10px;font-weight:700;color:#2d3748;text-transform:uppercase;"
        "letter-spacing:0.12em;margin:32px 0 4px;padding-bottom:4px;border-bottom:1px solid #1e2a38'>"
        "Evidence — supporting diagnostics</div>"
    )

    # ── T4: Degradation Mechanism Classifier (LLI vs LAM) ──────────────────
    with st.expander("⚗️ Degradation Mechanism Classifier — LLI vs LAM", expanded=False):
        try:
            import numpy as _np_mech
            _mech_signals = {}
            _mech_confidence_notes = []

            # Signal 1: CE trend slope → LLI indicator (works for all chemistries)
            if "coulombic_efficiency" in df.columns:
                _ce_valid = df[["cycle_number", "coulombic_efficiency"]].dropna()
                if len(_ce_valid) >= 10:
                    _ce_arr = _ce_valid["coulombic_efficiency"].values
                    _cy_arr = _ce_valid["cycle_number"].values.astype(float)
                    _ce_slope = _np_mech.polyfit(_cy_arr, _ce_arr, 1)[0]
                    _ce_deficit_pct = (1.0 - _ce_arr.mean()) * 100
                    _mech_signals["lli_ce_slope"] = _ce_slope
                    _mech_signals["lli_ce_deficit"] = _ce_deficit_pct
                    _mech_confidence_notes.append("CE trend")

            # Signal 2: Capacity fade linearity — linear fade = LLI, accelerating = LAM
            if "soh_pct" in df.columns:
                _soh_valid = df[["cycle_number", "soh_pct"]].dropna()
                if len(_soh_valid) >= 20:
                    _cy_s = _soh_valid["cycle_number"].values.astype(float)
                    _soh_s = _soh_valid["soh_pct"].values
                    # Fit linear + quadratic — if quadratic term >> 0, accelerating (LAM)
                    _cy_norm = (_cy_s - _cy_s.min()) / max(_cy_s.max() - _cy_s.min(), 1)
                    _p2 = _np_mech.polyfit(_cy_norm, _soh_s, 2)
                    _nonlinearity = float(_p2[0])  # positive curvature = accelerating fade
                    _fade_total = float(_soh_s[0] - _soh_s[-1]) if len(_soh_s) > 0 else 0
                    _mech_signals["lam_nonlinearity"] = _nonlinearity
                    _mech_signals["fade_total"] = _fade_total
                    _mech_confidence_notes.append("fade shape")

            # Signal 3: Resistance rise rate → SEI/LAM indicator
            if "resistance_normalized" in df.columns:
                _r_valid = df[["cycle_number", "resistance_normalized"]].dropna()
                if len(_r_valid) >= 10:
                    _r_slope = _np_mech.polyfit(
                        _r_valid["cycle_number"].values.astype(float),
                        _r_valid["resistance_normalized"].values, 1
                    )[0]
                    _mech_signals["resistance_slope"] = _r_slope * 1000  # Ω/1000cy
                    _mech_confidence_notes.append("resistance")

            # ── Classification logic ──
            _lli_score = 0
            _lam_score = 0

            _ce_slope_val = _mech_signals.get("lli_ce_slope", 0)
            if _ce_slope_val < -1e-6:   # declining CE → LLI
                _lli_score += 3
            _ce_def = _mech_signals.get("lli_ce_deficit", 0)
            if _ce_def > 0.05:          # CE deficit > 0.05% → active LLI
                _lli_score += 2

            _nonlin = _mech_signals.get("lam_nonlinearity", 0)
            if _nonlin < -0.5:          # accelerating fade → LAM
                _lam_score += 3
            elif _nonlin > 0.5:         # decelerating (stabilising) → LLI
                _lli_score += 1

            _r_slope = _mech_signals.get("resistance_slope", 0)
            if _r_slope > 0.02:         # fast resistance rise → LAM (particle contact loss)
                _lam_score += 2
            elif 0.005 < _r_slope <= 0.02:
                _lli_score += 1         # moderate rise → SEI (LLI-associated)

            # Verdict
            _total = _lli_score + _lam_score
            if _total == 0:
                _verdict = "Insufficient data"
                _verdict_color = "#718096"
                _verdict_icon = "○"
                _verdict_body = "Not enough degradation signals to classify mechanism. Continue cycling."
            elif _lli_score > _lam_score * 1.5:
                _verdict = "LLI — Loss of Lithium Inventory"
                _verdict_color = "#f6ad55"
                _verdict_icon = "◑"
                _verdict_body = (
                    "Declining coulombic efficiency and/or near-linear capacity fade indicate "
                    "that cyclable lithium is being consumed by SEI layer growth. "
                    "Root cause: calendar aging, elevated temperature, or overcharge events. "
                    "Mitigation: reduce SOC window, lower charge temperature, avoid prolonged full-charge storage."
                )
            elif _lam_score > _lli_score * 1.5:
                _verdict = "LAM — Loss of Active Material"
                _verdict_color = "#fc8181"
                _verdict_icon = "◕"
                _verdict_body = (
                    "Accelerating capacity fade and/or fast resistance rise indicate electrode "
                    "active sites are being lost. Root cause: high C-rate stress, mechanical particle "
                    "cracking, or lithium plating followed by dead lithium formation. "
                    "Mitigation: reduce peak charge/discharge rate, improve thermal management."
                )
            else:
                _verdict = "Mixed LLI + LAM"
                _verdict_color = "#b794f4"
                _verdict_icon = "●"
                _verdict_body = (
                    "Both LLI and LAM mechanisms are active simultaneously. "
                    "Typical of aged cells under combined calendar and cycle stress. "
                    "Prioritise temperature control (targets LLI) while also reducing peak C-rate (targets LAM)."
                )

            # Confidence from number of available signals
            _conf = len(_mech_confidence_notes)
            _conf_label = {0: "No data", 1: "Low", 2: "Medium", 3: "High"}.get(_conf, "High")
            _conf_color = {"No data": "#4a5568", "Low": "#f6ad55", "Medium": "#68d391", "High": "#68d391"}.get(_conf_label, "#68d391")

            # Render verdict card
            _md_html(
                f"<div style='background:#1e2a38;border:1px solid #2d3748;border-radius:10px;"
                f"padding:16px 20px;margin:8px 0 12px'>"
                f"<div style='display:flex;align-items:center;gap:12px;margin-bottom:10px'>"
                f"<span style='font-size:22px'>{_verdict_icon}</span>"
                f"<div>"
                f"<div style='font-size:14px;font-weight:700;color:{_verdict_color}'>{_verdict}</div>"
                f"<div style='font-size:11px;color:#718096;margin-top:2px'>"
                f"Confidence: <span style='color:{_conf_color};font-weight:600'>{_conf_label}</span>"
                f" · Signals used: {', '.join(_mech_confidence_notes) if _mech_confidence_notes else 'none'}"
                f"</div></div></div>"
                f"<div style='font-size:12px;color:#a0aec0;line-height:1.65'>{_verdict_body}</div>"
                f"</div>"
            )

            # Signal breakdown metrics
            if _mech_signals:
                _mc1, _mc2, _mc3 = st.columns(3)
                with _mc1:
                    if "lli_ce_deficit" in _mech_signals:
                        st.metric("LLI Score", f"{_lli_score}",
                                  help="CE decline + linear fade pattern")
                with _mc2:
                    if "lam_nonlinearity" in _mech_signals:
                        st.metric("LAM Score", f"{_lam_score}",
                                  help="Accelerating fade + resistance rise")
                with _mc3:
                    if "resistance_slope" in _mech_signals:
                        st.metric("R Rise Rate", f"{_mech_signals['resistance_slope']:.3f} Ω/kcy",
                                  help="Resistance increase per 1000 cycles")
        except Exception as _e_mech:
            st.info(f"Mechanism classifier unavailable: {_e_mech}")

    # ── dQ/dV Degradation Analysis ──────────────────────────────────────────
    # LFP cells (Severson) have a flat discharge plateau — the LiCoO₂ OCV
    # polynomial used in simulate_vq_curve() does not apply to LFP chemistry.
    # Showing simulated LiCoO₂ dQ/dV peaks for an LFP cell is physically wrong.
    _is_lfp = cell_id.startswith("S-")   # Severson cells are all LFP
    _dqdv_prov = _analysis_provenance(cell_id, "derived")
    _dqdv_badge = {"measured": "◐ SIMULATED", "simulated": "◐ SIMULATED", "synthetic": "○ SYNTHETIC"}[_dqdv_prov]
    _dqdv_title = (
        "dQ/dV Proxy — LiCoO₂ model only (not applicable to LFP)"
        if _is_lfp
        else f"dQ/dV Simulated Proxy (LiCoO₂ model) — {_dqdv_badge}"
    )
    with st.expander(f"🔬 {_dqdv_title}", expanded=False):
        if _is_lfp:
            st.warning(
                "**dQ/dV analysis is not available for LFP cells (Severson 2019).**\n\n"
                "The simulation uses a LiCoO₂ OCV polynomial with a well-defined voltage peak. "
                "LFP has a flat ≈3.2 V plateau — no peak exists, so the simulated features carry "
                "no physical meaning for this chemistry. "
                "Real dQ/dV for LFP requires per-cycle measured V(Q) curves from the cycler."
            )
        else:
          try:
            from dqdv import simulate_vq_curve
            _prov_dqdv = _analysis_provenance(cell_id, "derived")
            _md_html(provenance_banner(_prov_dqdv,
                "<strong>Simulated proxy — not measured data.</strong> "
                "V(Q) and dQ/dV curves are computed by <code>simulate_vq_curve()</code>, a "
                "LiCoO&#x2082; OCV polynomial model parameterised from the cell's measured "
                "capacity and resistance. No voltage traces were logged during cycling. "
                "These features are physically meaningful only for LiCoO&#x2082;-family chemistries."
            ))

            n_cycles = len(df)
            pct_indices = [int(n_cycles * p) for p in [0.05, 0.25, 0.50, 0.75, 0.95]]
            pct_indices = [min(max(i, 0), n_cycles - 1) for i in pct_indices]
            rep_rows = [df.iloc[i] for i in pct_indices]

            # ── A) V(Q) Curve Overlay ──
            _COLORS = ["#63b3ed", "#7fbfea", "#f6ad55", "#ed8936", "#fc8181"]
            fig_vq = go.Figure()
            for i, (row, color) in enumerate(zip(rep_rows, _COLORS)):
                try:
                    cap = float(row["capacity_ah"])
                    res = float(row.get("resistance_ohm", 0.02))
                    Q, V = simulate_vq_curve(cap, res)
                    fig_vq.add_trace(go.Scatter(
                        x=Q.tolist(), y=V.tolist(),
                        mode="lines",
                        name=f"Cycle {int(row['cycle_number'])}",
                        line=dict(color=color, width=1.8),
                        hovertemplate="Q=%{x:.3f} Ah  V=%{y:.3f} V<extra>Cycle " + str(int(row["cycle_number"])) + "</extra>",
                    ))
                except Exception:
                    pass
            fig_vq.update_layout(
                **base_layout(
                    height=300, legend=LEGEND_H,
                    xaxis=dict(title="Discharge Capacity (Ah)", zeroline=False),
                    yaxis=dict(title="Voltage (V)", zeroline=False),
                ),
            )
            fig_vq.update_layout(title=dict(text="Simulated Discharge Voltage Curves (V vs Q)", font=dict(size=12, color="#a0aec0"), x=0))
            st.plotly_chart(fig_vq, use_container_width=True)

            # ── B) dQ/dV Peak Trend ──
            dqdv_cols = ["dqdv_peak_soc", "dqdv_peak_value"]
            if all(c in df.columns for c in dqdv_cols):
                fig_peak = go.Figure()
                fig_peak.add_trace(go.Scatter(
                    x=_rdf["cycle_number"], y=_rdf["dqdv_peak_soc"],
                    name="Peak SOC Position", line=dict(color="#63b3ed", width=2),
                    hovertemplate="Cycle %{x}: %{y:.3f}<extra>Peak SOC</extra>",
                ))
                fig_peak.add_trace(go.Scatter(
                    x=_rdf["cycle_number"], y=_rdf["dqdv_peak_value"],
                    name="Peak Amplitude (Ah/V)", line=dict(color="#f6ad55", width=2),
                    yaxis="y2",
                    hovertemplate="Cycle %{x}: %{y:.2f} Ah/V<extra>Peak Amplitude</extra>",
                ))
                fig_peak.update_layout(
                    **base_layout(
                        height=300, legend=LEGEND_H,
                        xaxis=dict(title="Cycle", zeroline=False),
                        yaxis=dict(title="Peak SOC Position", zeroline=False, color="#63b3ed"),
                        yaxis2=dict(title="Peak Amplitude (Ah/V)", overlaying="y", side="right",
                                    zeroline=False, color="#f6ad55"),
                    ),
                )
                fig_peak.update_layout(title=dict(text="dQ/dV Peak Shift Over Aging", font=dict(size=12, color="#a0aec0"), x=0))
                st.plotly_chart(fig_peak, use_container_width=True)
                st.caption("Peak SOC shifts left and amplitude drops as active material is lost — a direct electrochemical signature of degradation.")

            # ── C) FWHM Trend ──
            if "dqdv_fwhm" in df.columns:
                fig_fwhm = go.Figure()
                fig_fwhm.add_trace(go.Scatter(
                    x=_rdf["cycle_number"], y=_rdf["dqdv_fwhm"],
                    line=dict(color="#48bb78", width=2),
                    hovertemplate="Cycle %{x}: %{y:.4f} Ah<extra>FWHM</extra>",
                    showlegend=False,
                ))
                fig_fwhm.update_layout(
                    **base_layout(
                        height=260, legend=LEGEND_H,
                        xaxis=dict(title="Cycle", zeroline=False),
                        yaxis=dict(title="FWHM (Ah)", zeroline=False),
                    ),
                )
                fig_fwhm.update_layout(title=dict(text="dQ/dV Peak Width (FWHM) — Broadening = increased heterogeneity", font=dict(size=12, color="#a0aec0"), x=0))
                st.plotly_chart(fig_fwhm, use_container_width=True)

            # ── ⚗️ Degradation Mechanism — single classification card ──
            _dom_mech, _dom_explain = "Inconclusive", "Insufficient dQ/dV data for classification."
            if all(c in df.columns for c in ["dqdv_peak_soc", "dqdv_peak_value", "dqdv_fwhm"]):
                import numpy as _np2
                _em = df[df.cycle_number <= df.cycle_number.quantile(0.10)]
                _lm = df[df.cycle_number >= df.cycle_number.quantile(0.90)]
                if len(_em) > 0 and len(_lm) > 0 and _em.dqdv_peak_value.mean() > 1e-9 and _em.dqdv_fwhm.mean() > 1e-9:
                    _ps  = _em.dqdv_peak_soc.mean() - _lm.dqdv_peak_soc.mean()
                    _ad  = (_em.dqdv_peak_value.mean() - _lm.dqdv_peak_value.mean()) / _em.dqdv_peak_value.mean() * 100
                    _fw  = (_lm.dqdv_fwhm.mean() - _em.dqdv_fwhm.mean()) / _em.dqdv_fwhm.mean() * 100
                    if _ps > 0.05 and _ad > 10:
                        _dom_mech = "LLI + LAM"
                        _dom_explain = "Both SEI lithium loss and electrode material loss are active. Typical of combined calendar + high-rate cycling stress."
                    elif _ps > 0.05:
                        _dom_mech = "LLI — Loss of Lithium Inventory"
                        _dom_explain = "SEI growth is consuming cyclable lithium. Peak shift to lower SOC values. Common in calendar-aged or high-temperature cells."
                    elif _ad > 15:
                        _dom_mech = "LAM — Loss of Active Material"
                        _dom_explain = "Electrode active sites are being lost. Peak amplitude decreasing proportionally to capacity loss. Common in high C-rate cycling."
                    elif _fw > 20:
                        _dom_mech = "LAM-NE — Graphite heterogeneity"
                        _dom_explain = "Peak broadening without large position shift suggests graphite particle cracking or lithium plating creating heterogeneous intercalation."
                    else:
                        _dom_mech = "Early stage"
                        _dom_explain = "Degradation has not yet reached a classifiable signature. Monitor after further cycling."
            _mech_col = "#f6ad55" if "LAM" in _dom_mech or "LLI" in _dom_mech else "#8896a8"
            _md_html(
                f"<div style='background:#1e2a38;border:1px solid #2d3748;border-radius:8px;"
                f"padding:12px 16px;margin-top:8px'>"
                f"<div style='font-size:10px;color:#4a5568;text-transform:uppercase;letter-spacing:0.08em;"
                f"margin-bottom:4px'>Dominant mechanism</div>"
                f"<div style='font-size:15px;font-weight:700;color:{_mech_col};margin-bottom:6px'>{_dom_mech}</div>"
                f"<div style='font-size:12px;color:#a0aec0;line-height:1.5'>{_dom_explain}</div>"
                f"</div>"
            )
          except Exception as _e:
            st.info(f"dQ/dV analysis unavailable: {_e}")

    # ── ⚡ Coulombic Efficiency ──────────────────────────────────────────────
    if "coulombic_efficiency" in df.columns:
        _ce_prov = _analysis_provenance(cell_id, "cycle")
        _ce_badge = "● MEASURED" if _ce_prov == "measured" else "○ SYNTHETIC"
        with st.expander(f"⚡ Coulombic Efficiency (CE) Analysis — {_ce_badge}", expanded=False):
            try:
                ce_latest  = float(df["coulombic_efficiency"].iloc[-1])
                ce_initial = float(df["coulombic_efficiency"].iloc[:10].mean())
                ce_drop    = ce_initial - ce_latest

                _ce1, _ce2, _ce3 = st.columns(3)
                with _ce1:
                    st.metric("Current CE", f"{ce_latest*100:.3f}%",
                              help="Q_discharge / Q_charge — lithium consumed by SEI each cycle")
                with _ce2:
                    st.metric("CE Drop from Cycle 1", f"{ce_drop*100:.3f}%",
                              delta=f"{-ce_drop*100:.3f}%",
                              help="Cumulative lithium inventory loss signature")
                with _ce3:
                    ce_risk = "High" if ce_latest < 0.993 else ("Moderate" if ce_latest < 0.997 else "Low")
                    st.metric("Lithium Loss Risk", ce_risk,
                              help="< 99.7%: moderate SEI growth; < 99.3%: accelerated LLI")

                _md_html("""<div style="font-size:12px;color:#8896a8;margin:8px 0 12px;line-height:1.6"><strong style="color:#a0aec0">Why CE matters:</strong> Every cycle where CE &lt; 100% permanently loses cyclable lithium to the SEI layer. A CE drop from 99.95% → 99.30% may seem small but represents ~0.65% lithium lost per cycle — the dominant degradation mechanism in calendar-aged cells. CATL and BYD track cumulative CE deficit as the primary warranty signal for LLI-dominated failures.</div>""")

                # CE trend chart
                _rdf_ce = _resample_df(df[df["coulombic_efficiency"].notna()])
                fig_ce = go.Figure()
                fig_ce.add_trace(go.Scatter(
                    x=_rdf_ce["cycle_number"].tolist(),
                    y=(_rdf_ce["coulombic_efficiency"] * 100).tolist(),
                    name="CE per cycle", mode="lines",
                    line=dict(color="#4a5568", width=1),
                    hovertemplate="Cycle %{x}: %{y:.4f}%<extra>CE</extra>",
                ))
                if "ce_rolling_30cy" in df.columns:
                    fig_ce.add_trace(go.Scatter(
                        x=_rdf_ce["cycle_number"].tolist(),
                        y=(_rdf_ce["ce_rolling_30cy"] * 100).tolist(),
                        name="30-cycle rolling avg", mode="lines",
                        line=dict(color="#63b3ed", width=2),
                        hovertemplate="Cycle %{x}: %{y:.4f}%<extra>30cy avg</extra>",
                    ))
                fig_ce.add_hline(y=99.70, line=dict(color="#f6ad55", width=1, dash="dot"),
                                 annotation_text="99.70% — moderate risk threshold",
                                 annotation=dict(font=dict(size=9, color="#f6ad55")))
                fig_ce.add_hline(y=99.30, line=dict(color="#fc8181", width=1, dash="dot"),
                                 annotation_text="99.30% — high LLI risk",
                                 annotation=dict(font=dict(size=9, color="#fc8181")))
                fig_ce.update_layout(
                    **base_layout(
                        height=280, legend=LEGEND_H,
                        xaxis=dict(title="Cycle", zeroline=False),
                        yaxis=dict(title="Coulombic Efficiency (%)", zeroline=False),
                    ),
                )
                fig_ce.update_layout(title=dict(text="Coulombic Efficiency — Q_discharge / Q_charge", font=dict(size=12, color="#a0aec0"), x=0))
                st.plotly_chart(fig_ce, use_container_width=True)

                # Cumulative lithium loss
                ce_deficit = (1.0 - _rdf_ce["coulombic_efficiency"]).cumsum()
                fig_lii = go.Figure()
                fig_lii.add_trace(go.Scatter(
                    x=_rdf_ce["cycle_number"].tolist(),
                    y=(ce_deficit * float(df["capacity_ah"].iloc[0]) * 1000).tolist(),
                    fill="tozeroy", fillcolor="rgba(252,129,129,0.08)",
                    line=dict(color="#fc8181", width=2),
                    hovertemplate="Cycle %{x}: %{y:.2f} mAh cumulative LLI<extra></extra>",
                    showlegend=False,
                ))
                fig_lii.update_layout(
                    **base_layout(
                        height=220, legend=LEGEND_H,
                        xaxis=dict(title="Cycle", zeroline=False),
                        yaxis=dict(title="Cumulative Li loss (mAh)", zeroline=False),
                    ),
                )
                fig_lii.update_layout(title=dict(text="Cumulative Lithium Inventory Loss (LLI) from CE Deficit", font=dict(size=12, color="#a0aec0"), x=0))
                st.plotly_chart(fig_lii, use_container_width=True)
            except Exception as _ce_e:
                st.info(f"CE analysis unavailable: {_ce_e}")

    # ── Advanced diagnostics (C1: secondary expanders, collapsed by default) ──
    _md_html(
        "<div style='font-size:10px;font-weight:700;color:#2d3748;text-transform:uppercase;"
        "letter-spacing:0.12em;margin:24px 0 4px;padding-bottom:4px;border-bottom:1px solid #1e2a38'>"
        "Advanced diagnostics</div>"
    )

    # ── 📈 Energy Throughput ─────────────────────────────────────────────────
    if "cumulative_kwh" in df.columns:
        _thru_badge = "● MEASURED" if cell_id in NASA_CELL_IDS else "○ SYNTHETIC"
        with st.expander(f"📈 Energy & Capacity Throughput — {_thru_badge}", expanded=False):
            try:
                total_kwh = float(df["cumulative_kwh"].iloc[-1])
                total_ah  = float(df["cumulative_ah"].iloc[-1])
                eq_cy     = float(df["equivalent_cycles"].iloc[-1]) if "equivalent_cycles" in df.columns and not pd.isna(df["equivalent_cycles"].iloc[-1]) else None

                _t1, _t2, _t3 = st.columns(3)
                with _t1:
                    st.metric("Total Energy Delivered", f"{total_kwh:.2f} kWh",
                              help="Cumulative energy throughput — BYD/CATL warranty metric")
                with _t2:
                    st.metric("Total Capacity Delivered", f"{total_ah:.0f} Ah",
                              help="Cumulative Ah throughput across all cycles")
                with _t3:
                    if eq_cy is not None:
                        raw_cy = int(df["cycle_number"].iloc[-1])
                        st.metric("Equivalent Cycles", f"{eq_cy:,.0f}",
                                  delta=f"{eq_cy - raw_cy:+,.0f} vs raw",
                                  help="Stress-normalized cycle count: raw cycles × stress factor")
                    else:
                        st.metric("Equivalent Cycles", "—", help="Not available for this data source")

                fig_kwh = go.Figure()
                fig_kwh.add_trace(go.Scatter(
                    x=_rdf["cycle_number"].tolist(),
                    y=_rdf["cumulative_kwh"].tolist(),
                    fill="tozeroy", fillcolor="rgba(99,179,237,0.07)",
                    line=dict(color="#63b3ed", width=2),
                    hovertemplate="Cycle %{x}: %{y:.3f} kWh delivered<extra></extra>",
                    showlegend=False,
                ))
                fig_kwh.update_layout(
                    **base_layout(
                        height=250, legend=LEGEND_H,
                        xaxis=dict(title="Cycle", zeroline=False),
                        yaxis=dict(title="Cumulative kWh", zeroline=False),
                    ),
                )
                fig_kwh.update_layout(title=dict(text="Cumulative Energy Throughput (kWh) — Warranty Accounting Metric", font=dict(size=12, color="#a0aec0"), x=0))
                st.plotly_chart(fig_kwh, use_container_width=True)
            except Exception as _te:
                st.info(f"Throughput analysis unavailable: {_te}")

    # ── ⚠ Lithium Plating Risk Score (M5) ────────────────────────────────────
    with st.expander("⚠ Lithium Plating Risk", expanded=False):
        _md_html(
            "<div style='font-size:12px;color:#8896a8;margin-bottom:10px'>"
            "Lithium plating (Li deposition on the anode) is the primary cause of sudden capacity loss "
            "and thermal runaway risk. Detected via Coulombic Efficiency dips below 99.5% — each dip "
            "indicates a cycle where more lithium was lost than consumed by normal SEI growth. "
            "Correlation with high C-rate or low temperature (if available) increases confidence."
            "</div>"
        )
        try:
            _ce_col = "coulombic_efficiency" if "coulombic_efficiency" in df.columns else None
            if _ce_col is None:
                _empty_state("CE data unavailable",
                             "Coulombic Efficiency data is required to compute plating risk. "
                             "This column was not found in the feature set for this cell.",
                             "→ Ensure the source data includes charge and discharge capacity per cycle.", "⚠")
            else:
                _ce_valid = df[_ce_col].dropna()
                # CE dips: readings below 99.5% threshold
                _PLATING_CE_THRESH = 0.995
                _dip_mask  = _ce_valid < _PLATING_CE_THRESH
                _n_dips    = int(_dip_mask.sum())
                _dip_cycles = df.loc[_ce_valid[_dip_mask].index, "cycle_number"].tolist() if _n_dips else []

                # Consecutive dip runs → sustained plating events
                _runs, _in_run, _run_len = 0, False, 0
                for _d in _dip_mask:
                    if _d:
                        _run_len += 1
                        if _run_len >= 3:
                            if not _in_run:
                                _runs += 1
                                _in_run = True
                    else:
                        _in_run, _run_len = False, 0

                # Risk score: 0-100
                _dip_rate   = _n_dips / max(len(_ce_valid), 1)
                _risk_score = min(100, int(_dip_rate * 400 + _runs * 15))
                _risk_label = ("Low" if _risk_score < 25 else
                               "Moderate" if _risk_score < 55 else
                               "High" if _risk_score < 80 else "Critical")
                _risk_colour = (UI_GREEN if _risk_score < 25 else
                                UI_YELLOW if _risk_score < 55 else
                                "#e53e3e" if _risk_score < 80 else "#c53030")

                # Score strip
                _pr1, _pr2, _pr3, _pr4 = st.columns(4)
                _pr1.metric("Plating Risk Score", f"{_risk_score}/100",
                            help="0=negligible · 25+=moderate · 55+=high · 80+=critical")
                _pr2.metric("Risk Level", _risk_label)
                _pr3.metric("CE Dip Events", f"{_n_dips}")
                _pr4.metric("Sustained Runs (≥3cy)", f"{_runs}")

                # Colour bar
                _md_html(
                    f"<div style='background:#1e2a38;border-radius:6px;height:8px;margin:8px 0 12px;overflow:hidden'>"
                    f"<div style='background:{_risk_colour};width:{_risk_score}%;height:100%;border-radius:6px;"
                    f"transition:width 0.3s'></div></div>"
                )

                # CE dip chart
                if _n_dips > 0:
                    _fig_plat = go.Figure()
                    _fig_plat.add_trace(go.Scatter(
                        x=df["cycle_number"].tolist(), y=(_ce_valid * 100).reindex(df.index).tolist(),
                        name="CE (%)", line=dict(color="#63b3ed", width=1.5),
                        hovertemplate="Cycle %{x}: CE %{y:.2f}%<extra></extra>",
                    ))
                    _fig_plat.add_hline(y=99.5, line_dash="dash", line_color="#fc8181", line_width=1,
                                        annotation_text="Plating threshold (99.5%)",
                                        annotation_font=dict(color="#fc8181", size=10))
                    if _dip_cycles:
                        _dip_ce = [float(_ce_valid.iloc[_ce_valid.index.get_loc(
                            df[df["cycle_number"] == c].index[0])] * 100)
                                   if len(df[df["cycle_number"] == c]) > 0 else None
                                   for c in _dip_cycles[:50]]
                        _fig_plat.add_trace(go.Scatter(
                            x=_dip_cycles[:50], y=_dip_ce,
                            mode="markers", name="CE dip (plating event)",
                            marker=dict(color="#fc8181", size=7, symbol="x"),
                        ))
                    _fig_plat.update_layout(
                        **base_layout(
                            height=220,
                            xaxis=dict(title="Cycle"),
                            yaxis=dict(title="CE (%)", range=[99.0, 100.05]),
                        ),
                    )
                    _fig_plat.update_layout(legend=dict(font=dict(size=10, color="#718096")))
                    st.plotly_chart(_fig_plat, use_container_width=True)

                # Interpretation
                _plat_text = {
                    "Low":      "CE stays consistently above 99.5%. No plating signals detected. "
                                "Current operating conditions appear safe.",
                    "Moderate": f"{_n_dips} CE dips detected below 99.5%. This may indicate isolated "
                                "plating events. Review charging conditions — reduce C-rate at low temperatures.",
                    "High":     f"{_n_dips} CE dips with {_runs} sustained run(s). Repeated plating is "
                                "occurring. Reduce maximum C-rate and avoid charging below 10°C. "
                                "Consider capacity check cycle to quantify lithium inventory loss.",
                    "Critical": f"CRITICAL: {_n_dips} CE dips, {_runs} sustained events. Active lithium "
                                "plating is likely. Risk of thermal runaway elevated. Immediate inspection "
                                "recommended. Do not fast-charge this cell.",
                }[_risk_label]
                _md_html(
                    f"<div style='background:{_risk_colour}11;border-left:3px solid {_risk_colour};"
                    f"border-radius:6px;padding:10px 14px;font-size:12px;color:#a0aec0'>"
                    f"<strong style='color:{_risk_colour}'>{_risk_label} risk:</strong> {_plat_text}"
                    f"</div>"
                )
        except Exception as _plat_err:
            st.info(f"Plating risk analysis unavailable: {_plat_err}")

    # ── H5: Tier 3 — Advanced / expert analysis ──────────────────────────────
    _md_html(
        "<div style='font-size:10px;font-weight:700;color:#2d3748;text-transform:uppercase;"
        "letter-spacing:0.12em;margin:32px 0 4px;padding-bottom:4px;border-bottom:1px solid #1e2a38'>"
        "Advanced analysis — physics models &amp; expert diagnostics</div>"
    )

    # ── 🔬 Resistance Component Proxy ──────────────────────────────────────
    _eis_badge = "◐ SIMULATED" if cell_id in NASA_CELL_IDS else "○ SYNTHETIC"
    with st.expander(f"🔬 Resistance Component Proxy (simulated) — {_eis_badge}", expanded=False):
        try:
            import numpy as _np_eis
            _md_html(provenance_banner(
                "simulated" if cell_id in NASA_CELL_IDS else "synthetic",
                "Impedance components (R_ohm, R_SEI, R_ct, σ_w) are derived from DC resistance via "
                "fixed physics-attribution fractions, <strong>not from frequency-domain impedance "
                "spectroscopy measurements</strong>. The Nyquist plot is computed from a Randles "
                "circuit model parameterised by these attributed values. "
                "Connect a real EIS instrument file (Gamry / BioLogic .DTA/.mpt) to replace this "
                "with measured impedance data."
            ))
            _eis_cols = ["r_ohm_eis", "r_sei", "r_ct", "sigma_w"]
            _has_eis  = all(c in df.columns for c in _eis_cols)
            if not _has_eis:
                st.info("EIS columns not available in this dataset. Regenerate data to enable.")
            else:
                st.caption(
                    "Randles-circuit decomposition of the measured DC resistance. "
                    "R_ohm (bulk electrolyte, constant), R_SEI (SEI layer, grows with √time), "
                    "R_ct (charge transfer, grows with cycle^0.6), σ_w (Warburg / diffusion coefficient)."
                )
                # Pick 3 lifecycle snapshots: early / mid / late
                _n = len(df)
                _snap_idx = [max(0, int(_n * f) - 1) for f in [0.05, 0.50, 0.95]]
                _snap_labels = ["Early (5%)", "Mid (50%)", "Late (95%)"]

                # Nyquist simulation
                _FREQ = _np_eis.logspace(5, -2, 60)
                _OMEGA = 2 * _np_eis.pi * _FREQ
                _nyq_colors = ["#48bb78", "#63b3ed", "#fc8181"]
                _fig_nyq = go.Figure()
                for _si, (_idx, _lbl, _col) in enumerate(zip(_snap_idx, _snap_labels, _nyq_colors)):
                    _row = df.iloc[_idx]
                    _r_ohm = float(_row["r_ohm_eis"])
                    _r_sei = float(_row["r_sei"])
                    _r_ct  = float(_row["r_ct"])
                    _sw    = float(_row["sigma_w"])
                    # CPE-based Randles circuit
                    _alpha_sei, _alpha_dl = 0.82, 0.88
                    _Q_sei, _Q_dl = 8e-6, 3e-5
                    _Z_sei_cpe = 1.0 / (_Q_sei * (1j * _OMEGA) ** _alpha_sei)
                    _Z_dl_cpe  = 1.0 / (_Q_dl  * (1j * _OMEGA) ** _alpha_dl)
                    _Z_sei = (_r_sei * _Z_sei_cpe) / (_r_sei + _Z_sei_cpe)
                    _Z_w   = _sw * (1 - 1j) / _np_eis.sqrt(_np_eis.maximum(_OMEGA, 1e-9))
                    _Z_ct  = (_r_ct * (_Z_dl_cpe + _Z_w)) / (_r_ct + _Z_dl_cpe + _Z_w)
                    _Z     = _r_ohm + _Z_sei + _Z_ct
                    _fig_nyq.add_trace(go.Scatter(
                        x=_Z.real.tolist(), y=(-_Z.imag).tolist(),
                        mode="lines", name=_lbl,
                        line=dict(color=_col, width=2),
                        hovertemplate=f"<b>{_lbl}</b><br>Z' = %{{x:.4f}} Ω<br>-Z'' = %{{y:.4f}} Ω<extra></extra>",
                    ))
                _fig_nyq.update_layout(
                    **base_layout(
                        height=300, legend=LEGEND_H,
                        xaxis=dict(title="Z' (Ω) — Real", zeroline=False),
                        yaxis=dict(title="-Z'' (Ω) — Imaginary", zeroline=False),
                    ),
                )
                _fig_nyq.update_layout(title=dict(text="Nyquist Plot at 3 Lifecycle Stages (CPE Modified Randles)", font=dict(size=12, color="#a0aec0"), x=0))
                st.plotly_chart(_fig_nyq, use_container_width=True, config={**PLOTLY_CONFIG, "toImageButtonOptions": {**PLOTLY_CONFIG["toImageButtonOptions"], "filename": "nyquist_plot"}})

                # Component trend chart
                _fig_eis_trend = go.Figure()
                for _col_name, _label, _color in [
                    ("r_sei", "R_SEI (SEI layer)", "#f6ad55"),
                    ("r_ct",  "R_ct (charge transfer)", "#63b3ed"),
                    ("r_ohm_eis", "R_ohm (electrolyte)", "#48bb78"),
                ]:
                    _fig_eis_trend.add_trace(go.Scatter(
                        x=_rdf["cycle_number"].tolist(), y=_rdf[_col_name].tolist(),
                        mode="lines", name=_label,
                        line=dict(width=2),
                        hovertemplate=f"Cycle %{{x}}: %{{y:.4f}} Ω ({_label})<extra></extra>",
                    ))
                _fig_eis_trend.update_layout(
                    **base_layout(
                        height=270, legend=LEGEND_H,
                        xaxis=dict(title="Cycle", zeroline=False),
                        yaxis=dict(title="Resistance (Ω)", zeroline=False),
                    ),
                )
                _fig_eis_trend.update_layout(title=dict(text="Resistance Component Trends — Simulated Proxy", font=dict(size=12, color="#a0aec0"), x=0))
                st.plotly_chart(_fig_eis_trend, use_container_width=True, config={**PLOTLY_CONFIG, "toImageButtonOptions": {**PLOTLY_CONFIG["toImageButtonOptions"], "filename": "eis_component_trends"}})

                # Mechanism interpretation
                _late = df.iloc[-1]
                _r0   = df.iloc[0]["r_sei"]
                _sei_growth = (_late["r_sei"] - _r0) / max(_r0, 1e-9) * 100
                _ct_growth  = (_late["r_ct"]  - df.iloc[0]["r_ct"]) / max(df.iloc[0]["r_ct"], 1e-9) * 100
                if _sei_growth > _ct_growth * 1.3:
                    _mech = "Calendar / SEI-dominated"
                    _mech_color = "#f6ad55"
                    _mech_explain = "R_SEI growth outpaces R_ct — primary degradation is SEI thickening from calendar storage and temperature exposure."
                elif _ct_growth > _sei_growth * 1.3:
                    _mech = "Cycle / Charge-transfer-dominated"
                    _mech_color = "#63b3ed"
                    _mech_explain = "R_ct growth outpaces R_SEI — primary degradation is charge-transfer impedance from active-material loss and lithium plating."
                else:
                    _mech = "Mixed SEI + charge-transfer"
                    _mech_color = "#48bb78"
                    _mech_explain = "Balanced SEI and charge-transfer growth — both calendar and cycling contribute comparably."
                _md_html(f"""<div style="background:rgba(26,32,44,0.7);border:1px solid #2d3748;border-radius:8px;padding:12px 16px;font-size:13px"><span style="color:{_mech_color};font-weight:700">{_mech}</span><span style="color:#a0aec0;margin-left:10px">{_mech_explain}</span><br><span style="color:#8896a8;font-size:12px;margin-top:4px;display:block">R_SEI growth: {_sei_growth:.1f}% · R_ct growth: {_ct_growth:.1f}%</span></div>""")
        except Exception as _eis_e:
            st.info(f"EIS analysis unavailable: {_eis_e}")

    # ── 🧪 Formation Protocol Analysis ─────────────────────────────────────
    _form_badge = "◐ SIMULATED" if cell_id in NASA_CELL_IDS else "○ SYNTHETIC"
    with st.expander(f"🧪 Formation Protocol Analysis — {_form_badge}", expanded=False):
        try:
            import numpy as _np_form
            _md_html(provenance_banner(
                "simulated" if cell_id in NASA_CELL_IDS else "synthetic",
                "Formation metrics (ICL, CE stabilisation) are read from the first cycles of "
                "this cell's cycle-summary data. For synthetic cells this data was generated, "
                "not measured. For NASA cells it is measured cycle capacity — "
                "but NASA cells were cycled at fixed conditions after formation, not logged during "
                "formation itself. CE values for NASA cells are <strong>not directly measured</strong>; "
                "they are model outputs from <code>generate_cell_data()</code> logic."
            ))
            _form_cycles = df[df["cycle_number"] <= 10].copy() if len(df) >= 10 else df.copy()
            if len(_form_cycles) < 3:
                st.info("Need at least 3 cycles to analyse formation.")
            else:
                st.caption(
                    "Formation = first 3–10 cycles. SEI forms on the anode, consuming cyclable lithium "
                    "(Irreversible Capacity Loss, ICL). CE rises steeply from ~90–95% toward >99.9% as the "
                    "SEI stabilises. Rate and magnitude predict long-term calendar ageing."
                )
                _q0   = float(_form_cycles["capacity_ah"].iloc[0])
                _q3   = float(_form_cycles["capacity_ah"].iloc[min(2, len(_form_cycles)-1)])
                _icl  = (_q0 - _q3) / max(_q0, 1e-9) * 100
                _ce0  = float(_form_cycles["coulombic_efficiency"].iloc[0]) * 100 if "coulombic_efficiency" in _form_cycles.columns else None
                _ce3  = float(_form_cycles["coulombic_efficiency"].iloc[min(2, len(_form_cycles)-1)]) * 100 if "coulombic_efficiency" in _form_cycles.columns else None

                _fc1, _fc2, _fc3 = st.columns(3)
                _fc1.metric("ICL (Cycles 1→3)", f"{_icl:.2f}%", help="Irreversible Capacity Loss during formation. Target <2% for LiCoO₂.")
                if _ce0 is not None:
                    _fc2.metric("CE Cycle 1", f"{_ce0:.2f}%", help="First-cycle CE; ~90–95% is normal — SEI consumes lithium.")
                    _fc3.metric("CE Cycle 3", f"{_ce3:.2f}%", delta=f"+{_ce3-_ce0:.2f}pp", help="CE should stabilise toward 99.9% by cycle 10.")

                # CE stabilisation curve
                if "coulombic_efficiency" in df.columns:
                    _form_plot = df[df["cycle_number"] <= 30].copy()
                    _fig_form = go.Figure()
                    _fig_form.add_trace(go.Scatter(
                        x=_form_plot["cycle_number"].tolist(),
                        y=(_form_plot["coulombic_efficiency"] * 100).tolist(),
                        mode="lines+markers",
                        marker=dict(size=5, color="#48bb78"),
                        line=dict(color="#48bb78", width=2),
                        name="CE",
                        hovertemplate="Cycle %{x}: CE = %{y:.3f}%<extra></extra>",
                    ))
                    _fig_form.add_hline(y=99.9, line_dash="dot", line_color="#f6ad55", annotation_text="99.9% — SEI stabilisation target", annotation_position="bottom right")
                    _fig_form.update_layout(
                        **base_layout(
                            height=260, legend=LEGEND_H,
                            xaxis=dict(title="Cycle", zeroline=False),
                            yaxis=dict(title="Coulombic Efficiency (%)", zeroline=False),
                        ),
                    )
                    _fig_form.update_layout(title=dict(text="CE Stabilisation — Formation Window (First 30 Cycles)", font=dict(size=12, color="#a0aec0"), x=0))
                    st.plotly_chart(_fig_form, use_container_width=True, config={**PLOTLY_CONFIG, "toImageButtonOptions": {**PLOTLY_CONFIG["toImageButtonOptions"], "filename": "ce_formation"}})

                # Lifetime prediction from formation metrics
                _icl_risk = "Low" if _icl < 1.5 else ("Moderate" if _icl < 3.0 else "High")
                _risk_color = {"Low": "#48bb78", "Moderate": "#f6ad55", "High": "#fc8181"}[_icl_risk]
                _md_html(f"""<div style="background:rgba(26,32,44,0.7);border:1px solid #2d3748;border-radius:8px;padding:12px 16px;font-size:13px"><span style="color:{_risk_color};font-weight:700">ICL Risk: {_icl_risk}</span><span style="color:#a0aec0;margin-left:10px">ICL = {_icl:.2f}% — literature correlation: cells with ICL &lt;1.5% retain &gt;90% SOH beyond 500 cycles (Severson et al. 2019).</span></div>""")
        except Exception as _form_e:
            st.info(f"Formation analysis unavailable: {_form_e}")

    # ── 📊 Rate Capability Analysis ─────────────────────────────────────────
    _rate_badge = "○ SYNTHETIC" if (cell_id not in NASA_CELL_IDS and not cell_id.startswith("S-")) else "◐ SIMULATED"
    with st.expander(f"📊 Rate Capability — {_rate_badge}", expanded=False):
        try:
            import numpy as _np_rate
            _md_html(provenance_banner(
                "simulated" if cell_id in NASA_CELL_IDS else "synthetic",
                "Capacity retention at each C-rate is computed from "
                "<code>Q(C) = Q_nom × SOH × exp(−k_rate × C^1.4)</code>, where k_rate scales "
                "with measured internal resistance. <strong>No multi-rate characterisation test was "
                "performed.</strong> Real rate capability requires dedicated CCCV cycling at each "
                "C-rate on a cell tester (Arbin, Maccor, Neware, etc.)."
            ))
            st.caption(
                "Rate capability shows how much capacity is retained at higher charge/discharge rates. "
                "Capacity drop at 2C vs C/5 quantifies power-fade — critical for EV and fast-charge applications."
            )
            _latest = df.iloc[-1]
            _soh_frac = float(_latest["soh_pct"]) / 100.0
            _r_now    = float(_latest.get("resistance_ohm", 0.150))
            _q_nom    = float(df["capacity_ah"].iloc[0])

            # Physics-based C-rate derating: Q(C) = Q_nom × SOH × exp(-k_rate × C^1.4)
            # k_rate scales with resistance: higher R → more rate-sensitive
            _k_rate    = 0.03 * (_r_now / 0.150)
            _c_rates   = [0.05, 0.10, 0.20, 0.50, 1.0, 2.0, 5.0]
            _c_labels  = ["C/20", "C/10", "C/5", "C/2", "1C", "2C", "5C"]
            _capacities = [_q_nom * _soh_frac * _np_rate.exp(-_k_rate * c ** 1.4) for c in _c_rates]
            _retention  = [100.0 * cap / max(_capacities[0], 1e-9) for cap in _capacities]

            _fig_rate = go.Figure()
            _fig_rate.add_trace(go.Bar(
                x=_c_labels, y=_retention,
                marker_color=["#48bb78" if r >= 90 else "#f6ad55" if r >= 75 else "#fc8181" for r in _retention],
                text=[f"{r:.1f}%" for r in _retention],
                textposition="outside",
                hovertemplate="%{x}: %{y:.1f}% retention<extra></extra>",
            ))
            _fig_rate.update_layout(
                **base_layout(
                    height=280, legend=LEGEND_H,
                    xaxis=dict(title="C-rate", zeroline=False),
                    yaxis=dict(title="Capacity Retention (%)", range=[0, 115], zeroline=False),
                ),
            )
            _fig_rate.update_layout(title=dict(text="Rate Capability: Capacity Retention at Current SOH", font=dict(size=12, color="#a0aec0"), x=0))
            st.plotly_chart(_fig_rate, use_container_width=True, config={**PLOTLY_CONFIG, "toImageButtonOptions": {**PLOTLY_CONFIG["toImageButtonOptions"], "filename": "rate_capability"}})

            _ret_2c = _retention[5]
            _ret_msg = f"At 2C (fast charge), this cell retains {_ret_2c:.1f}% of its C/5 capacity."
            _ret_color = "#48bb78" if _ret_2c >= 85 else "#f6ad55" if _ret_2c >= 70 else "#fc8181"
            _md_html(f"""<div style="background:rgba(26,32,44,0.7);border:1px solid #2d3748;border-radius:8px;padding:12px 16px;font-size:13px"><span style="color:{_ret_color};font-weight:700">{_ret_msg}</span><span style="color:#a0aec0;margin-left:10px">k_rate = {_k_rate:.3f} (resistance-scaled). >85% at 2C = good fast-charge fitness; &lt;70% = rate-limited application only.</span></div>""")
        except Exception as _rate_e:
            st.info(f"Rate capability analysis unavailable: {_rate_e}")

    # ── ⚛️ Physics-Based RUL Projection (PyBaMM SPM) ────────────────────────
    # C2: surface GBRT vs PyBaMM delta when cache is warm
    _pb2_key = f"pybamm_{cell_id}_{st.session_state.get('eol_threshold_pct', 80)}"
    _pb2_pre = st.session_state.get(_pb2_key, {})
    if (_pb2_pre and not _pb2_pre.get("error") and _pb2_pre.get("rul_physics")
            and rul_reliable and "rul_pred" in latest.index
            and latest["rul_pred"] is not None):
        _gbrt_rul2 = float(latest["rul_pred"])
        _phys_rul2 = int(_pb2_pre["rul_physics"])
        _gap_pct2 = abs(_phys_rul2 - _gbrt_rul2) / max(_gbrt_rul2, 1) * 100
        _gap_col2 = "#48bb78" if _gap_pct2 < 15 else "#f6ad55" if _gap_pct2 < 35 else "#fc8181"
        _conv_label = (
            "✓ Models converge — high confidence" if _gap_pct2 < 15 else
            f"⚡ Models diverge {_gap_pct2:.0f}% — expand for interpretation" if _gap_pct2 < 35 else
            f"⚠ Large divergence {_gap_pct2:.0f}% — review recommended"
        )
        _md_html(
            f"<div style='font-size:12px;margin:4px 0 6px;padding:6px 14px;"
            f"background:#1e2a38;border-radius:6px;border-left:3px solid {_gap_col2}'>"
            f"<span style='color:{_gap_col2};font-weight:600'>{_conv_label}</span>"
            f"<span style='color:#718096;margin-left:10px'>"
            f"Physics: <strong style='color:#68d391'>{_phys_rul2:,} cy</strong> &nbsp;·&nbsp; "
            f"Data: <strong style='color:#f6ad55'>{int(_gbrt_rul2):,} cy</strong></span></div>"
        )
    with st.expander("Model Comparison — Physics (PyBaMM SPM) vs Data (GBRT)", expanded=False):
        _md_html(
            "<div style='display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:14px'>"
            "<div style='background:#0e1117;border:1px solid #2d3748;border-radius:8px;padding:12px'>"
            "<div style='font-size:10px;font-weight:700;color:#68d391;text-transform:uppercase;"
            "letter-spacing:0.08em;margin-bottom:6px'>⚛ PyBaMM SPM — Physics model</div>"
            "<div style='font-size:12px;color:#a0aec0;line-height:1.6'>"
            "Derives nominal capacity from electrochemistry (Single Particle Model), then fits "
            "<code>SOH(n) = 1 − β√n</code> to the measured history. "
            "The √n term reflects diffusion-limited SEI growth slowing over time.<br>"
            "<span style='color:#4a5568;font-size:11px'>Strong in: early life · new cells · unknown chemistry.<br>"
            "Weak in: post-knee acceleration · non-SEI failure modes.</span>"
            "</div></div>"
            "<div style='background:#0e1117;border:1px solid #2d3748;border-radius:8px;padding:12px'>"
            "<div style='font-size:10px;font-weight:700;color:#f6ad55;text-transform:uppercase;"
            "letter-spacing:0.08em;margin-bottom:6px'>📊 GBRT — Data-driven model</div>"
            "<div style='font-size:12px;color:#a0aec0;line-height:1.6'>"
            "Gradient-boosted trees trained across the full cell population under leave-cell-out "
            "validation. Extrapolates the current rolling fade rate forward linearly.<br>"
            "<span style='color:#4a5568;font-size:11px'>Strong in: cells with rich history · mid–late life.<br>"
            "Weak in: early life (fade still decelerating) · sparse data.</span>"
            "</div></div>"
            "</div>"
        )
        _pybamm_cache_key = f"pybamm_{cell_id}_{st.session_state.get('eol_threshold_pct', 80)}"
        if _pybamm_cache_key not in st.session_state:
            with st.spinner("Running PyBaMM SPM — first run only, cached after…"):
                try:
                    import sys as _sys2
                    _src2 = os.path.join(os.path.dirname(__file__), "..", "src")
                    if _src2 not in _sys2.path:
                        _sys2.path.insert(0, _src2)
                    from pybamm_rul import project_rul as _project_rul
                    _eol_thr = float(st.session_state.get("eol_threshold_pct", 80.0))
                    _pb_res  = _project_rul(
                        cell_id, df,
                        data_mode=st.session_state.get("data_mode", "synthetic"),
                        eol_threshold=_eol_thr,
                        project_cycles=600,
                    )
                    st.session_state[_pybamm_cache_key] = _pb_res
                except Exception as _pb_install_err:
                    st.session_state[_pybamm_cache_key] = {"error": str(_pb_install_err)}

        _pb = st.session_state.get(_pybamm_cache_key, {})
        if _pb.get("error"):
            st.info(f"Physics projection unavailable: {_pb['error']}")
        elif _pb.get("proj_cycles"):
            # ── Parameter summary strip ──
            _pc1, _pc2, _pc3, _pc4 = st.columns(4)
            _pc1.metric("Parameter set", _pb["chem_label"].split("(")[0].strip())
            _pc2.metric("SPM nominal capacity", f"{_pb['spm_capacity_ah']:.3f} Ah")
            _pc3.metric("Fitted β (SEI)", f"{_pb['beta']:.5f}")
            _rul_ph = _pb.get("rul_physics")
            _pc4.metric("Physics RUL", f"{_rul_ph:,} cy" if _rul_ph is not None else "—")

            # ── Projection chart ──
            _fig_pb = go.Figure()

            # Measured SOH history (resampled)
            _fig_pb.add_trace(go.Scatter(
                x=_rdf["cycle_number"].tolist(),
                y=_rdf["soh_pct"].tolist(),
                name="Measured SOH",
                line=dict(color="#63b3ed", width=2),
                hovertemplate="Cycle %{x}: %{y:.1f}% SOH<extra>Measured</extra>",
            ))

            # Physics projection — 95% uncertainty band (β ± 2σ)
            if _pb.get("proj_soh_lo") and _pb.get("proj_soh_hi"):
                _fig_pb.add_trace(go.Scatter(
                    x=_pb["proj_cycles"] + list(reversed(_pb["proj_cycles"])),
                    y=_pb["proj_soh_hi"] + list(reversed(_pb["proj_soh_lo"])),
                    fill="toself",
                    fillcolor="rgba(104,211,145,0.10)",
                    line=dict(color="rgba(0,0,0,0)"),
                    name="Physics 95% CI (β ± 2σ)",
                    showlegend=True,
                    hoverinfo="skip",
                ))
            # Physics projection central line
            _fig_pb.add_trace(go.Scatter(
                x=_pb["proj_cycles"],
                y=_pb["proj_soh"],
                name="Physics projection (SPM · SEI)",
                line=dict(color="#68d391", width=2, dash="dot"),
                hovertemplate="Cycle %{x}: %{y:.1f}% SOH<extra>SPM central</extra>",
            ))

            # GBRT ML estimate as comparison (linear fade forward)
            _fade_50 = float(latest.get("fade_rate_50cy", 0)) if hasattr(latest, "get") else float(latest["fade_rate_50cy"]) if "fade_rate_50cy" in latest.index else 0
            if _fade_50 > 0 and _rul_ph:
                _ml_fut_cy  = _pb["proj_cycles"][:min(len(_pb["proj_cycles"]), _rul_ph + 50)]
                _ml_fut_soh = [current_soh - _fade_50 * 100 * (c - int(latest["cycle_number"])) for c in _ml_fut_cy]
                _ml_fut_soh = [max(0, s) for s in _ml_fut_soh]
                _fig_pb.add_trace(go.Scatter(
                    x=_ml_fut_cy,
                    y=_ml_fut_soh,
                    name="ML linear extrapolation (GBRT fade)",
                    line=dict(color="#f6ad55", width=1, dash="dash"),
                    hovertemplate="Cycle %{x}: %{y:.1f}% SOH<extra>GBRT</extra>",
                ))

            # Temperature sensitivity bands (H3) — β(T) = β₀·exp(−Ea/RT)
            _temp_colours = {"15°C": "#63b3ed", "25°C": "#68d391", "35°C": "#fc8181"}
            for _t_label, _t_soh in _pb.get("temp_scenarios", {}).items():
                if _t_label == "25°C":
                    continue   # 25°C is already the central line
                _fig_pb.add_trace(go.Scatter(
                    x=_pb["proj_cycles"], y=_t_soh,
                    name=f"SPM @ {_t_label}",
                    line=dict(color=_temp_colours.get(_t_label, "#a0aec0"), width=1, dash="longdash"),
                    opacity=0.6,
                    hovertemplate=f"Cycle %{{x}}: %{{y:.1f}}% SOH<extra>SPM {_t_label}</extra>",
                ))

            # EOL threshold line
            _eol_thr_val = float(st.session_state.get("eol_threshold_pct", 80.0))
            _fig_pb.add_hline(
                y=_eol_thr_val,
                line_dash="dash", line_color="#fc8181", line_width=1,
                annotation_text=f"EOL {_eol_thr_val:.0f}%",
                annotation_font=dict(color="#fc8181", size=10),
            )

            _fig_pb.update_layout(
                **base_layout(
                    height=340,
                    xaxis=dict(title="Cycle"),
                    yaxis=dict(title="SOH %",
                               range=[max(0, min(_pb["proj_soh"] or [60]) - 5), 102]),
                ),
            )
            _fig_pb.update_layout(
                legend=dict(font=dict(size=10, color="#718096")),
                title=dict(
                    text=f"PyBaMM SPM · {_pb['chem_label']} · SEI growth fade",
                    font=dict(size=12, color="#a0aec0"), x=0,
                ),
            )
            st.plotly_chart(_fig_pb, use_container_width=True)

            # ── Model comparison diagnostic ───────────────────────────────
            # Pull GBRT RUL prediction for this cell if available
            _rul_ml = None
            if "rul_pred" in latest.index:
                _v = latest["rul_pred"]
                if _v == _v and _v is not None:   # not NaN
                    _rul_ml = int(float(_v))

            _rul_ph_val = _rul_ph or 0
            _rul_diff   = _rul_ph_val - (_rul_ml or _rul_ph_val)
            _rul_diff_pct = abs(_rul_diff) / max(_rul_ph_val, 1) * 100

            # Determine cell life regime from fade trajectory
            _fade_30_val  = float(latest["fade_rate_30cy"]) if "fade_rate_30cy" in latest.index else 0
            _fade_50_val  = float(latest["fade_rate_50cy"]) if "fade_rate_50cy" in latest.index else 0
            _fade_accel   = (_fade_30_val - _fade_50_val) / max(_fade_50_val, 1e-9)
            _knee_detected = knee.get("detected", False) if isinstance(knee, dict) else False

            if current_soh >= 90:
                _regime = "early"
                _regime_label = "Early life (SOH ≥ 90%)"
            elif _knee_detected or _fade_accel > 0.25:
                _regime = "post_knee"
                _regime_label = "Post-knee / accelerating fade"
            elif current_soh >= 80:
                _regime = "mid"
                _regime_label = "Mid life (80–90% SOH)"
            else:
                _regime = "late"
                _regime_label = "Late life (SOH < 80%)"

            # Build physics model explanation
            _phys_explain = {
                "early": (
                    f"At {current_soh:.1f}% SOH the cell is still in early life. "
                    f"SEI growth is diffusion-limited — the rate of Li inventory loss slows as "
                    f"1/(2√n) because the SEI layer itself impedes further electrolyte reduction. "
                    f"With β = {_pb['beta']:.5f}, the model predicts the fade rate will "
                    f"<strong style='color:#68d391'>continue to decelerate</strong>. "
                    f"This is the regime where the √n model is most physically accurate."
                ),
                "mid": (
                    f"At {current_soh:.1f}% SOH the cell is in mid life — the √n model is a "
                    f"reasonable approximation but the SEI layer is now thick enough that "
                    f"secondary mechanisms (electrolyte depletion, active material loss) "
                    f"may be starting to contribute. β = {_pb['beta']:.5f} was fitted to the "
                    f"full measured history; if fade has been <em>accelerating recently</em>, "
                    f"this β underestimates future loss."
                ),
                "post_knee": (
                    f"The cell has passed its knee point (or 30-cycle fade rate exceeds "
                    f"50-cycle rate by >{_fade_accel*100:.0f}%). The √n SEI model "
                    f"<strong style='color:#fc8181'>does not capture this acceleration</strong> — "
                    f"SEI-only models have no mechanism for lithium plating, particle cracking, "
                    f"or electrolyte depletion, all of which cause superlinear fade. "
                    f"β = {_pb['beta']:.5f} was fitted to the full history including early slow fade, "
                    f"so the physics projection will be <strong style='color:#fc8181'>over-optimistic</strong>."
                ),
                "late": (
                    f"At {current_soh:.1f}% SOH the cell is in late life. The SEI model "
                    f"(β = {_pb['beta']:.5f}) was calibrated on the full cycle history, but "
                    f"late-life degradation is typically dominated by particle cracking and "
                    f"electrolyte depletion — neither appears in the SPM. "
                    f"The physics projection should be treated as an <em>optimistic bound</em> only."
                ),
            }[_regime]

            # Build ML model explanation
            _ml_explain = (
                f"The GBRT model extrapolates the <strong>current 50-cycle rolling fade rate "
                f"({_fade_50_val*1000:.3f} mSOH/cy)</strong> forward linearly. "
                f"It learned from {'{}'} cells under leave-cell-out validation, so it captures "
                f"population-level degradation patterns — but it has no electrochemical mechanism. "
                f"Linear extrapolation overestimates remaining life in early aging (fade is still "
                f"decelerating) and may underestimate it mid-life if the current window happens to "
                f"fall on a temporary rough patch."
            ).format("N")

            # Build divergence explanation
            if _rul_ml is None:
                _div_explain = (
                    "ML RUL was not available for this cell (reliability gate not met or "
                    "model not calibrated). Physics-only estimate shown."
                )
                _div_colour = "#718096"
            elif _rul_diff_pct < 10:
                _div_explain = (
                    f"The two estimates agree within {_rul_diff_pct:.0f}% "
                    f"({_rul_ph_val} vs {_rul_ml} cycles). "
                    f"This is expected in mid life when the √n curve is approximately linear "
                    f"over short windows. <strong style='color:#68d391'>High confidence "
                    f"in the {_rul_ph_val}-cycle estimate.</strong>"
                )
                _div_colour = "#68d391"
            elif _rul_diff > 0:
                _div_explain = (
                    f"Physics estimates <strong style='color:#68d391'>{_rul_ph_val} cycles</strong> "
                    f"vs ML <strong style='color:#f6ad55'>{_rul_ml} cycles</strong> "
                    f"— physics is more optimistic by {_rul_diff} cycles ({_rul_diff_pct:.0f}%). "
                    + (
                        "In early life this is expected: the √n model predicts ongoing deceleration "
                        "that the linear GBRT cannot see. <strong>Use the physics estimate with caution "
                        "until fade stabilises.</strong>"
                        if _regime == "early" else
                        "This divergence in mid-to-late life may indicate the GBRT is "
                        "over-weighting a recent high-fade window. "
                        "<strong>Conservative engineering decision: use the ML (lower) estimate.</strong>"
                    )
                )
                _div_colour = "#f6ad55"
            else:
                _div_explain = (
                    f"ML estimates <strong style='color:#68d391'>{_rul_ml} cycles</strong> "
                    f"vs physics <strong style='color:#fc8181'>{_rul_ph_val} cycles</strong> "
                    f"— ML is more optimistic by {-_rul_diff} cycles ({_rul_diff_pct:.0f}%). "
                    + (
                        "Post-knee, the √n model's fitted β was anchored to early slow fade "
                        "and is now over-projecting. The GBRT is responding to the recent "
                        "acceleration. <strong style='color:#fc8181'>Use the ML (lower) estimate "
                        "— the physics model is not capturing the acceleration mechanism.</strong>"
                        if _regime == "post_knee" else
                        "The SEI model predicts faster fade than the current GBRT window. "
                        "Worth investigating whether recent cycles show a change in operating "
                        "conditions (temperature, C-rate, depth of discharge)."
                    )
                )
                _div_colour = "#fc8181"

            # Render 3-section card
            _md_html(
                f"<div style='background:#111827;border:1px solid #2d3748;border-radius:10px;"
                f"padding:18px 20px;margin-top:8px;font-size:12px;line-height:1.7'>"

                # Section A — Physics model
                f"<div style='margin-bottom:14px'>"
                f"<div style='font-size:10px;font-weight:700;color:#68d391;text-transform:uppercase;"
                f"letter-spacing:0.08em;margin-bottom:5px'>⚛ PyBaMM SPM · SEI Growth Model</div>"
                f"<div style='color:#a0aec0'>{_phys_explain}</div>"
                f"<div style='color:#4a5568;font-size:11px;margin-top:4px'>"
                f"Parameter set: {_pb['chem_label']} &nbsp;·&nbsp; "
                f"β = {_pb['beta']:.5f} &nbsp;·&nbsp; "
                f"Nominal capacity (SPM): {_pb['spm_capacity_ah']:.3f} Ah"
                f"</div></div>"

                # Section B — ML model
                f"<div style='border-top:1px solid #1e2a38;padding-top:12px;margin-bottom:14px'>"
                f"<div style='font-size:10px;font-weight:700;color:#f6ad55;text-transform:uppercase;"
                f"letter-spacing:0.08em;margin-bottom:5px'>📊 GBRT · Linear Extrapolation</div>"
                f"<div style='color:#a0aec0'>{_ml_explain}</div>"
                f"<div style='color:#4a5568;font-size:11px;margin-top:4px'>"
                f"Current fade rate: {_fade_50_val*1000:.3f} mSOH/cy (50-cy rolling) &nbsp;·&nbsp; "
                f"Regime: {_regime_label}"
                f"</div></div>"

                # Section C — Divergence verdict
                f"<div style='border-top:1px solid #1e2a38;padding-top:12px;"
                f"background:{_div_colour}0d;border-radius:6px;padding:12px 14px;margin-top:2px'>"
                f"<div style='font-size:10px;font-weight:700;color:{_div_colour};text-transform:uppercase;"
                f"letter-spacing:0.08em;margin-bottom:5px'>⚖ Model Verdict</div>"
                f"<div style='color:#a0aec0'>{_div_explain}</div>"
                f"</div>"

                f"</div>"
            )


# ---------------------------------------------------------------------------
# Page: Insights
# ---------------------------------------------------------------------------

def page_insights(df: pd.DataFrame, bundle: dict, cell_id: str,
                  cell_ids: list | None = None, active_fdfs: dict | None = None):
    _action_bar("insights")
    st.markdown("# Insights")

    # Warn if this bundle was trained on fewer than 3 cells (uploaded data path)
    if bundle["metrics"].get("lco_limited"):
        n = bundle["metrics"].get("n_cells", "?")
        st.markdown(
            f"<div style='background:rgba(183,121,31,0.10);border:1px solid rgba(183,121,31,0.35);"
            f"border-radius:10px;padding:12px 18px;margin-bottom:16px'>"
            f"<span style='font-weight:700;color:#f6ad55'>⚠ LCO trained on {n} cells</span>"
            f"<span style='font-size:13px;color:#fefcbf;margin-left:10px'>"
            f"Reliability estimates are less stable than with 3+ cells. "
            f"Per-cell R² scores may not reflect true generalisation ability.</span>"
            f"</div>",
            unsafe_allow_html=True,
        )

    drivers     = top_drivers(bundle, model="soh", top_n=5)
    top_feature = drivers[0]["feature"]
    top_pct     = drivers[0]["importance_pct"]

    is_nasa_cell = cell_id in NASA_CELL_IDS
    model_label = (
        f"NASA real model · {bundle['metrics'].get('n_cells', 4)} cells"
        if is_nasa_cell
        else f"Synthetic model · {bundle['metrics'].get('n_cells', 8)} cells"
    )
    n_cells_trained = bundle["metrics"].get("n_cells", "—")
    _md_html(
        f"""
        <div class="hero-card">
            <div class="hero-label">Why this prediction? · SOH model · {model_label}</div>
            <div class="hero-value hero-blue" style="font-size:32px">
                {friendly(top_feature)}
            </div>
            <div class="hero-sub">
                Top-ranked by <strong style="color:#e2e8f0">split importance ({top_pct:.0f}%)</strong>
                — see the SHAP Attribution tab below for correct feature attribution
                that handles correlated fade-rate features.
                Internal resistance tracks SEI layer growth, the dominant degradation
                mechanism in LiCoO&#x2082; cells.
            </div>
        </div>
        """
    )

    def _importance_bar(fi: "pd.DataFrame", color_hi: str, height: int = 340) -> "go.Figure":
        labels = fi["importance_pct"].apply(
            lambda v: f"{v:.1f}%" if v >= fi["importance_pct"].max() * 0.03 else ""
        )
        fig = go.Figure(go.Bar(
            x=fi["importance_pct"], y=fi["label"],
            orientation="h",
            marker=dict(
                color=fi["importance_pct"],
                colorscale=[[0, "#1e2a38"], [0.4, "#1e2a38"], [1, color_hi]],
                showscale=False,
            ),
            text=labels,
            textposition="inside", insidetextanchor="end",
            textfont=dict(color="#ffffff", size=11),
            customdata=fi["importance_pct"],
            hovertemplate="<b>%{y}</b><br>Importance: %{customdata:.2f}%<extra></extra>",
        ))
        fig.update_layout(
            height=height,
            **base_layout(
                xaxis=dict(title="% importance", gridcolor="#232d3b", linecolor="#2d3748",
                           zeroline=False, range=[0, fi["importance_pct"].max() * 1.12]),
                yaxis=dict(autorange="reversed", gridcolor="#232d3b", linecolor="#2d3748"),
            ),
        )
        return fig

    # ── SHAP feature attribution ─────────────────────────────────────────────
    # SHAP (SHapley Additive exPlanations) correctly handles correlated features,
    # unlike split-based importances which over-credit the first feature in a
    # correlated group (e.g. fade_rate_10cy / _30cy / _50cy all measure the same
    # signal; split importance splits credit unpredictably among them).
    # SHAP uses the Shapley value from cooperative game theory: each feature's
    # contribution is its average marginal contribution across all feature subsets.
    _shap_tab, _imp_tab = st.tabs(["SHAP Attribution (recommended)", "Split Importance (legacy)"])

    with _shap_tab:
        _md_html(provenance_banner(
            "simulated" if cell_id in NASA_CELL_IDS else "synthetic",
            "SHAP values are computed from the trained GBRT model. They describe which features "
            "pushed this cell's SOH prediction higher or lower than the population average, "
            "correctly accounting for correlated features. "
            "<strong>Split-based importances (legacy tab) over-credit the first feature in a "
            "correlated group and are not reliable for feature selection.</strong>"
        ))
        try:
            _feat_names = bundle["feature_names"]
            _bundle_id = mode  # stable key per data source
            _mean_abs_soh, _mean_abs_rul = _get_shap_values(_bundle_id, bundle)
            if _mean_abs_soh is None:
                raise RuntimeError("SHAP computation failed")
            _shap_df_soh  = pd.DataFrame({
                "feature": _feat_names,
                "mean_abs_shap": _mean_abs_soh,
                "label": [friendly(f) for f in _feat_names],
            }).sort_values("mean_abs_shap", ascending=True).tail(12)

            _shap_df_rul  = pd.DataFrame({
                "feature": _feat_names,
                "mean_abs_shap": _mean_abs_rul,
                "label": [friendly(f) for f in _feat_names],
            }).sort_values("mean_abs_shap", ascending=True).tail(12)

            _sc1, _sc2 = st.columns(2)
            for _col, _shap_df, _color, _model_lbl in [
                (_sc1, _shap_df_soh, "#63b3ed", "SOH"),
                (_sc2, _shap_df_rul, "#48bb78", "RUL"),
            ]:
                with _col:
                    st.markdown(f"<div class='section-header'>SHAP Attribution — {_model_lbl} Model</div>", unsafe_allow_html=True)
                    _max_shap = _shap_df["mean_abs_shap"].max()
                    _fig_shap = go.Figure(go.Bar(
                        x=_shap_df["mean_abs_shap"],
                        y=_shap_df["label"],
                        orientation="h",
                        marker=dict(
                            color=_shap_df["mean_abs_shap"],
                            colorscale=[[0, "#1e2a38"], [0.4, "#1e2a38"], [1, _color]],
                            showscale=False,
                        ),
                        text=[f"{v:.4f}" for v in _shap_df["mean_abs_shap"]],
                        textposition="inside", insidetextanchor="end",
                        textfont=dict(color="#ffffff", size=10),
                        hovertemplate="<b>%{y}</b><br>Mean |SHAP|: %{x:.4f}<extra></extra>",
                    ))
                    _fig_shap.update_layout(
                        height=340,
                        **base_layout(
                            xaxis=dict(title="Mean |SHAP value|", gridcolor="#232d3b", linecolor="#2d3748",
                                       zeroline=False, range=[0, _max_shap * 1.12]),
                            yaxis=dict(autorange="reversed", gridcolor="#232d3b", linecolor="#2d3748"),
                        ),
                    )
                    _fig_shap.update_layout(title=dict(
                        text=f"SHAP Mean |φ| — {_model_lbl} · Top 12 features",
                        font=dict(size=12, color="#a0aec0"), x=0,
                    ))
                    st.plotly_chart(_fig_shap, use_container_width=True,
                                   config={**PLOTLY_CONFIG, "toImageButtonOptions": {**PLOTLY_CONFIG["toImageButtonOptions"], "filename": f"shap_{_model_lbl.lower()}"}})

            # Single-cell SHAP waterfall for the selected cell's latest cycle
            _X_this = df[bundle["feature_names"]].dropna().tail(1)
            if len(_X_this) > 0:
                _X_this_sc = _scaler.transform(_X_this)
                _shap_this  = _expl_soh.shap_values(_X_this_sc)[0]
                _base_val   = float(_expl_soh.expected_value)
                _pred_val   = _base_val + float(_shap_this.sum())
                _wf_df = pd.DataFrame({
                    "feature": [friendly(f) for f in _feat_names],
                    "shap": _shap_this,
                }).sort_values("shap", key=abs, ascending=True).tail(10)

                st.markdown("<div class='section-header'>SHAP Waterfall — Why is this cell's SOH predicted at this value?</div>", unsafe_allow_html=True)
                _colors_wf = ["#48bb78" if v > 0 else "#fc8181" for v in _wf_df["shap"]]
                _fig_wf = go.Figure(go.Bar(
                    x=_wf_df["shap"], y=_wf_df["feature"],
                    orientation="h",
                    marker_color=_colors_wf,
                    hovertemplate="<b>%{y}</b><br>SHAP: %{x:+.4f}<extra></extra>",
                    text=[f"{v:+.4f}" for v in _wf_df["shap"]],
                    textposition="outside",
                    textfont=dict(size=10, color="#a0aec0"),
                ))
                _fig_wf.update_layout(
                    height=320,
                    **base_layout(
                        xaxis=dict(title="SHAP value (impact on SOH prediction)", gridcolor="#232d3b",
                                   linecolor="#2d3748", zeroline=True, zerolinecolor="#4a5568"),
                        yaxis=dict(autorange="reversed", gridcolor="#232d3b", linecolor="#2d3748"),
                    ),
                )
                _fig_wf.update_layout(title=dict(
                    text=f"Waterfall: {cell_id} latest cycle · E[f(X)]={_base_val:.1f}% → prediction={_pred_val:.1f}%",
                    font=dict(size=12, color="#a0aec0"), x=0,
                ))
                st.plotly_chart(_fig_wf, use_container_width=True,
                               config={**PLOTLY_CONFIG, "toImageButtonOptions": {**PLOTLY_CONFIG["toImageButtonOptions"], "filename": "shap_waterfall"}})

        except ImportError:
            st.warning("SHAP not installed. Run `pip install shap` to enable SHAP attribution.")
        except Exception as _shap_e:
            st.info(f"SHAP computation unavailable: {_shap_e}")

    with _imp_tab:
        _md_html(provenance_banner(
            "simulated" if cell_id in NASA_CELL_IDS else "synthetic",
            "<strong>⚠ Split-based importances are unreliable for correlated features.</strong> "
            "fade_rate_10cy / _30cy / _50cy are heavily correlated; importance is distributed "
            "unpredictably among them based on which split the tree chooses first. "
            "Use the SHAP tab for correct attribution. "
            "These are shown here for reference only."
        ))
        col1, col2 = st.columns(2)
        with col1:
            st.markdown("<div class='section-header'>Split Importance — SOH Model</div>", unsafe_allow_html=True)
            fi_soh = feature_importance_df(bundle, model="soh")
            fi_soh["label"] = fi_soh["feature"].map(friendly)
            st.plotly_chart(_importance_bar(fi_soh, "#63b3ed"), use_container_width=True)
        with col2:
            st.markdown("<div class='section-header'>Split Importance — RUL Model</div>", unsafe_allow_html=True)
            fi_rul = feature_importance_df(bundle, model="rul")
            fi_rul["label"] = fi_rul["feature"].map(friendly)
            st.plotly_chart(_importance_bar(fi_rul, "#48bb78"), use_container_width=True)

    # Explain the profile difference (uses whichever fi_soh/fi_rul were last computed)
    try:
        top_soh_feat = fi_soh.iloc[0]["label"]
        top_rul_feat = fi_rul.iloc[0]["label"]
        if top_soh_feat != top_rul_feat:
            st.markdown(
                f"<div style='font-size:12px;color:#8896a8;background:#1a202c;border-left:3px solid #2d3748;"
                f"padding:10px 14px;border-radius:4px;margin-bottom:12px'>"
                f"<strong style='color:#a0aec0'>Why the profiles differ:</strong> "
                f"{top_soh_feat} dominates SOH prediction because it tracks cumulative degradation. "
                f"{top_rul_feat} dominates RUL prediction because it determines how fast the remaining "
                f"life gets consumed — a different question.</div>",
                unsafe_allow_html=True,
            )
    except Exception:
        pass

    # ── Model metrics ──
    st.markdown("<div class='section-header'>Model Performance — Multi-cell Training</div>", unsafe_allow_html=True)

    m = bundle["metrics"]
    mc1, mc2, mc3, mc4 = st.columns(4)
    lco_soh_r2 = m.get("lco_soh_r2", float("nan"))
    lco_rul_r2 = m.get("lco_rul_r2", float("nan"))
    rul_ok     = m.get("rul_reliable", True)

    mc1.metric(
        "SOH R² (LCO)",
        f"{m.get('lco_soh_r2', float('nan')):.3f}" if not (lco_soh_r2 != lco_soh_r2) else "—",
        help="Leave-cell-out R² — model trained on N-1 cells, tested on the held-out cell. "
             "This is the honest generalisation metric, not a row-level split.",
    )
    mc2.metric(
        "SOH MAE",
        f"{m['soh_mae']:.2f}%",
        help="Mean absolute SOH error on held-out test cycles (chronological split within training set).",
    )
    rul_label = f"{lco_rul_r2:.3f}" if rul_ok else f"{lco_rul_r2:.3f}*"
    mc3.metric(
        "RUL (LCO)",
        rul_label,
        help="Leave-cell-out R² for RUL." + ("" if rul_ok else " * below 0.30 floor — shown as 'Not calibrated' in UI."),
    )
    n_cells = m.get("n_cells", "—")
    n_rows  = m.get("n_rows", 0)
    mc4.metric(
        "Training",
        f"{n_cells} cells",
        help=f"{n_cells} cells / {n_rows:,} cycles total in the training set.",
    )

    with st.expander("What does resistance explaining 74% of SOH mean physically?"):
        st.markdown(
            """
            **Internal resistance is a direct proxy for SEI layer thickness.**
            The solid electrolyte interphase (SEI) grows on the anode with each cycle,
            consuming lithium inventory and increasing impedance. Both capacity fade and
            resistance growth are caused by the same underlying mechanism — so resistance
            is highly predictive of SOH, not because the model found a statistical
            shortcut, but because this is the actual physics.

            Real BMS systems (Battery Management Systems) use internal resistance as a
            primary health indicator for exactly this reason.

            **Why temperature explains 30% of RUL but not SOH:**
            Temperature affects how *fast* the remaining life gets consumed, not where
            the cell is right now. A Cell8 (40°C) and Cell7 (20°C) at the same SOH have
            very different futures. The RUL model correctly learns that temperature is
            the key signal for how much life is left.
            """
        )

    # ── Actual vs Predicted ──
    st.markdown("<div style='height:4px'></div>", unsafe_allow_html=True)

    td       = bundle["test_data"]
    actual   = td["y_soh_test"]
    pred     = td["soh_pred"]
    ax_min   = min(actual.min(), pred.min()) - 0.5
    ax_max   = max(actual.max(), pred.max()) + 0.5

    fig2 = go.Figure()
    fig2.add_trace(go.Scatter(
        x=[ax_min, ax_max], y=[ax_min, ax_max],
        mode="lines", line=dict(color="#2d3748", dash="dash", width=1),
        name="Perfect prediction", hoverinfo="skip",
    ))
    fig2.add_trace(go.Scatter(
        x=actual, y=pred, mode="markers",
        marker=dict(color="#63b3ed", size=4, opacity=0.4),
        name="Test cycles",
        hovertemplate="Actual: %{x:.1f}%<br>Predicted: %{y:.1f}%<extra></extra>",
    ))
    fig2.update_layout(
        height=300,
        **base_layout(
            xaxis=dict(title="Actual SOH %", gridcolor="#232d3b", linecolor="#2d3748",
                       zeroline=False, range=[ax_min, ax_max]),
            yaxis=dict(title="Predicted SOH %", gridcolor="#232d3b", linecolor="#2d3748",
                       zeroline=False, range=[ax_min, ax_max]),
        ),
    )
    st.plotly_chart(fig2, use_container_width=True)

    # ── 🌡️ Temperature–Degradation Analysis (Arrhenius) ──
    st.markdown("<div class='section-header'>Temperature–Degradation Analysis (Arrhenius)</div>", unsafe_allow_html=True)
    _afdfs = active_fdfs if active_fdfs is not None else {}
    if len(_afdfs) <= 1:
        _empty_state(
            "Multi-cell data required",
            "Cross-cell Arrhenius analysis needs at least 2 cells with temperature records.",
            "Switch to a multi-cell data source or upload multiple cells.",
            icon="📈",
        )
    else:
        import numpy as _np_arr
        _arr_rows = []
        for _cid, _cdf in _afdfs.items():
            _mean_temp      = float(_cdf["temperature_c"].mean())
            _mean_fade_rate = float(_cdf["fade_rate_50cy"].mean()) if "fade_rate_50cy" in _cdf.columns else float("nan")
            _arr_rows.append({"cell_id": _cid, "mean_temp": _mean_temp, "mean_fade_rate": _mean_fade_rate})
        _arr_df = pd.DataFrame(_arr_rows).dropna()
        if len(_arr_df) >= 2:
            _x = (1000 / (_arr_df["mean_temp"] + 273.15)).values
            _y = _np_arr.log(_arr_df["mean_fade_rate"].clip(lower=1e-9)).values
            _slope, _intercept = _np_arr.polyfit(_x, _y, 1)
            _x_line = _np_arr.linspace(_x.min(), _x.max(), 50)
            _y_line = _slope * _x_line + _intercept
            Ea_J_per_mol = -_slope * 8.314
            Ea_eV        = Ea_J_per_mol / 96485
            _fig_arr = go.Figure()
            _fig_arr.add_trace(go.Scatter(
                x=_x_line.tolist(), y=_y_line.tolist(),
                mode="lines", name="Trendline",
                line=dict(color="#4a5568", width=1.5, dash="dash"),
                hoverinfo="skip",
            ))
            _fig_arr.add_trace(go.Scatter(
                x=_x.tolist(), y=_y.tolist(),
                mode="markers+text",
                text=_arr_df["cell_id"].tolist(),
                textposition="top center",
                textfont=dict(size=10, color="#a0aec0"),
                marker=dict(color="#63b3ed", size=10, line=dict(color="#1a202c", width=1)),
                name="Cells",
                hovertemplate="<b>%{text}</b><br>1000/T=%{x:.3f}<br>ln(fade)=%{y:.3f}<extra></extra>",
            ))
            _fig_arr.update_layout(
                **base_layout(
                    height=320, legend=LEGEND_H,
                    xaxis=dict(title="1000 / T (K⁻¹)", gridcolor="#232d3b", linecolor="#2d3748", zeroline=False),
                    yaxis=dict(title="ln(Fade Rate per Cycle)", gridcolor="#232d3b", linecolor="#2d3748", zeroline=False),
                ),
            )
            _fig_arr.update_layout(title=dict(text="Arrhenius Plot: ln(Fade Rate) vs 1000/T", font=dict(size=12, color="#a0aec0"), x=0))
            st.plotly_chart(_fig_arr, use_container_width=True, config={**PLOTLY_CONFIG, "toImageButtonOptions": {**PLOTLY_CONFIG["toImageButtonOptions"], "filename": "arrhenius_plot"}})

            # Resistance Ea from same cells
            _arr_rows_r = []
            for _cid, _cdf in _afdfs.items():
                _mean_temp  = float(_cdf["temperature_c"].mean())
                _mean_r     = float(_cdf["resistance_ohm"].mean()) if "resistance_ohm" in _cdf.columns else float("nan")
                _arr_rows_r.append({"cell_id": _cid, "mean_temp": _mean_temp, "mean_r": _mean_r})
            _arr_df_r = pd.DataFrame(_arr_rows_r).dropna()
            Ea_eV_r = float("nan")
            if len(_arr_df_r) >= 2:
                _xr = (1000 / (_arr_df_r["mean_temp"] + 273.15)).values
                _yr = _np_arr.log(_arr_df_r["mean_r"].clip(lower=1e-9)).values
                _slope_r, _ = _np_arr.polyfit(_xr, _yr, 1)
                Ea_eV_r = -_slope_r * 8.314 / 96485

            # Ea display boxes
            _ac1, _ac2, _ac3 = st.columns(3)
            _ea_color = "#48bb78" if 0.35 <= Ea_eV <= 0.75 else "#f6ad55"
            _ac1.metric("Ea — Capacity Fade", f"{Ea_eV:.3f} eV", help="Activation energy from ln(fade rate) vs 1/T. Literature: 0.4–0.6 eV for LiCoO₂ SEI.")
            if not _np_arr.isnan(Ea_eV_r):
                _ac2.metric("Ea — Resistance Growth", f"{Ea_eV_r:.3f} eV", help="Activation energy from ln(resistance) vs 1/T.")
            _ac3.metric("Literature ref (LiCoO₂ SEI)", "0.4–0.6 eV", help="Birkl et al. 2017, Waldmann et al. 2014.")
            _md_html(f"""<div style="background:rgba(26,32,44,0.7);border:1px solid #2d3748;border-radius:8px;padding:12px 16px;font-size:13px;margin-top:8px"><span style="color:{_ea_color};font-weight:700">Ea = {Ea_eV:.3f} eV ({Ea_J_per_mol:.0f} J/mol)</span><span style="color:#a0aec0;margin-left:10px">{"Within expected range for thermally-activated SEI growth." if 0.35 <= Ea_eV <= 0.75 else "Outside typical LiCoO₂ range — verify temperature spread across cells."}</span></div>""")

            _arr_c1, _arr_c2 = st.columns(2)
            with _arr_c1:
                _arr_display = _arr_df.copy()
                _arr_display["avg temp (°C)"]   = _arr_display["mean_temp"].map("{:.1f}".format)
                _arr_display["avg fade rate"]    = _arr_display["mean_fade_rate"].map("{:.6f}".format)
                _max_fade = _arr_display["mean_fade_rate"].max()
                _arr_display["relative stress"]  = (_arr_display["mean_fade_rate"] / max(_max_fade, 1e-12)).map("{:.2f}×".format)
                st.dataframe(
                    _arr_display[["cell_id", "avg temp (°C)", "avg fade rate", "relative stress"]].rename(columns={"cell_id": "Cell ID"}),
                    use_container_width=True, hide_index=True,
                )
            with _arr_c2:
                st.caption(
                    "A linear Arrhenius relationship confirms thermally-activated degradation (SEI growth). "
                    "Slope gives activation energy — steeper = more temperature-sensitive chemistry. "
                    "Pre-exponential factor A = exp(intercept) characterises attempt frequency."
                )
        else:
            _empty_state(
                "Not enough cells for Arrhenius analysis",
                "Need at least 2 cells with valid temperature data to fit the Arrhenius model.",
                "Add a second data source or upload multi-cell data.",
                icon="🌡",
            )


